entries.content:
Add `Current state`, `implementation details`, `acceptance criteria` for `design/feature_descriptions/F_186_action_popup_bottom_of_chat_log.md`.&#x20;
update the field `status` in the markdown feature description file to `ready for implementation`.

Read all referenced files before you begin except `agents` files. it is possible that the file is not yet written. &#x20;
Ask any question if something is ambiguous or not yet clear.
Be brief, but never compress away the subject, timing, or causal chain. Define ambiguous technical phrases. use $caveman skill.

Do not stage or commit changes. You have no need for get at this time.

import { Box, Stack, Typography } from '@mui/material'
import { useLayoutEffect, useRef, useState, type UIEvent } from 'react'
import type { AgentConversation } from '../../../data/data_types'
import type { PopupRunStatus } from '../run/popup/action_popup_defaults'
import { ActionConversationEventRow } from './action_conversation_event_row'
import { ActionConversationMessage } from './action_conversation_message'
import { actionStatusLabel } from '../shared/action_status'
import { ConversationTimer } from './conversation_timer'
import { buildActionConversationRenderGroups } from './action_conversation_render_groups'
import { CompletedToolCallGroup } from './completed_tool_call_group'
import {
    createActionConversationReservationState,
    reservedActionConversationBlockCount,
    updateActionConversationReservation,
} from './action_conversation_reservation'
import { ActionConversationReservedBlock } from './action_conversation_reserved_block'
import { contextWindowUsedPercent } from './conversation_context_window'
import { reasoningDisplay } from './reasoning_display'

const CHAT_END_TOLERANCE = 4
const MIN_CHAT_HEIGHT = 96

interface ActionConversationChatProps {
    conversation: AgentConversation | null
    status: PopupRunStatus
}

function viewportIsAtEnd(viewport: HTMLDivElement) {
    return viewport.scrollHeight - viewport.clientHeight - viewport.scrollTop <= CHAT_END_TOLERANCE
}

function hasAgentActivity(conversation: AgentConversation) {
    return conversation.providerSessions.some(({ agent }) => agent === 'codex')
        || conversation.entries.some((entry) => entry.kind === 'message' && entry.agent === 'codex')
        || conversation.entries.some((entry) => entry.kind === 'event' && !!entry.providerItemId)
}

function conversationEventIsVisible(entry: AgentConversation['entries'][number]) {
    if (entry.kind !== 'event' || entry.type === 'diagnostic') return false
    if (entry.type !== 'reasoning' || entry.status !== 'completed') return true

    return reasoningDisplay(entry).hasText
}

function visibleConversationGroups(conversation: AgentConversation | null) {
    if (!conversation) return []
    const showEvents = hasAgentActivity(conversation)
    const visibleEntries = conversation.entries.filter((entry) => entry.kind === 'message'
        || (showEvents && conversationEventIsVisible(entry)))

    return buildActionConversationRenderGroups(visibleEntries)
}

/** Ordered user/assistant transcript shown above the popup prompt. */
export function ActionConversationChat({ conversation, status }: ActionConversationChatProps) {
    const groups = visibleConversationGroups(conversation)
    const viewportRef = useRef<HTMLDivElement>(null)
    const conversationPathRef = useRef<string | null | undefined>(undefined)
    const stuckToEndRef = useRef(true)
    const conversationPath = conversation?.path ?? null
    const [reservationState, setReservationState] = useState(() => updateActionConversationReservation(
        createActionConversationReservationState(),
        conversationPath,
        groups,
        status,
    ))
    const nextReservationState = updateActionConversationReservation(reservationState, conversationPath, groups, status)
    if (nextReservationState !== reservationState) setReservationState(nextReservationState)
    const reservedBlockCount = reservedActionConversationBlockCount(nextReservationState)
    const contextUsedPercent = contextWindowUsedPercent(conversation?.contextWindowUsage)

    const handleScroll = (event: UIEvent<HTMLDivElement>) => {
        stuckToEndRef.current = viewportIsAtEnd(event.currentTarget)
    }

    useLayoutEffect(() => {
        const viewport = viewportRef.current
        if (!viewport) return

        const conversationPath = conversation?.path ?? null
        const conversationChanged = conversationPathRef.current !== conversationPath
        conversationPathRef.current = conversationPath
        if (conversationChanged) stuckToEndRef.current = true
        if (!stuckToEndRef.current) return

        viewport.scrollTop = viewport.scrollHeight
    })

    return (
        <Stack spacing={1} sx={{ flex: 1, minHeight: 0 }}>
            <Stack
                aria-label="Conversation chat"
                onScroll={handleScroll}
                ref={viewportRef}
                spacing={1}
                sx={{ flex: 1, minHeight: MIN_CHAT_HEIGHT, overflowX: 'hidden', overflowY: 'auto' }}
            >
                {groups.map((group) => {
                    if (group.kind === 'completedToolCalls') {
                        return <CompletedToolCallGroup entries={group.entries} key={group.key} />
                    }

                    const { entry } = group
                    if (entry.kind === 'message') {
                        return (
                            <ActionConversationMessage
                                cardInternalId={conversation?.cardInternalId ?? null}
                                entry={entry}
                                key={group.key}
                            />
                        )
                    }

                    return <ActionConversationEventRow entry={entry} grouped={false} key={group.key} />
                })}
                {Array.from({ length: reservedBlockCount }, (_, index) => (
                    <ActionConversationReservedBlock key={`reserved-block-${index}`} />
                ))}
            </Stack>
            {conversation || status !== 'idle' ? (
                <Stack
                    aria-label="Conversation metadata"
                    direction="row"
                    spacing={1}
                    sx={{ alignItems: 'baseline', flexShrink: 0 }}
                >
                    {status !== 'idle' ? (
                        <Typography color={status === 'failed' ? 'error.main' : 'text.secondary'} role="status" variant="caption">
                            {actionStatusLabel(status)}
                        </Typography>
                    ) : null}
                    {conversation ? (
                        <ConversationTimer completedAt={conversation.completedAt} startedAt={conversation.startedAt} status={status} />
                    ) : null}
                    <Box sx={{ flex: 1 }} />
                    {contextUsedPercent !== null ? (
                        <Typography color="text.secondary" component="span" variant="caption">
                            context: {contextUsedPercent}%
                        </Typography>
                    ) : null}
                </Stack>
            ) : null}
        </Stack>
    )
}

import ArrowUpwardOutlined from '@mui/icons-material/ArrowUpwardOutlined'
import StopOutlined from '@mui/icons-material/StopOutlined'
import { Box, Button, IconButton, Tooltip } from '@mui/material'
import CalendarOutline from 'mdi-material-ui/CalendarOutline'
import Play from 'mdi-material-ui/Play'
import { useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import type { ActionRunSettingsStore } from '../../../../services/actions/action_run_settings_service'
import { useActionRunSelector } from '../../../hooks/use_action_runs'
import type { ActionConversationStore } from '../../conversation/action_conversation_store'
import type { ActionHistoryStore } from '../state/action_history_store'
import {
    cancelPopupAction,
    currentActionPromptDraft,
    finishPopupAction,
    runPopupAction,
} from './action_popup_operations'
import { actionPopupRunDisabled } from './action_popup_run_disabled'
import type { ActionRunInputStore } from '../state/action_run_input_store'
import type { ActionRunResultStore } from '../state/action_run_result_store'
import type { ActionScheduleStore } from '../schedule/action_schedule_store'
import { ActionUsageSummaryOwner } from './action_usage_summary_owner'
import { useActionRunSettings } from '../../shared/use_action_run_settings'
import { ActionPopupFinishButton } from './action_popup_finish_button'
import type { ActionUsageScopeStore } from './action_usage_scope_store'
import { ActionAgentSelectors } from '../../agent/action_agent_selectors'

interface ActionPopupBottomRowProps {
    action: ActionDefinition
    assignmentContext: ActionContext
    conversationStore: ActionConversationStore
    historyStore: ActionHistoryStore
    /** 2 call sites: for agents it is embedded inside input. commands have no input, but need bottom row for config and info */
    embedded?: boolean
    inputStore: ActionRunInputStore
    resultStore: ActionRunResultStore
    runValidationError: string | null
    scheduleStore: ActionScheduleStore
    settingsStore: ActionRunSettingsStore
    usageScopeStore: ActionUsageScopeStore
}

/** Agent settings, usage, and run controls for the popup footer. */
export function ActionPopupBottomRow(props: ActionPopupBottomRowProps) {
    const {
        action, assignmentContext, conversationStore, embedded = false, historyStore, inputStore, resultStore,
        runValidationError, scheduleStore, settingsStore, usageScopeStore,
    } = props
    const settings = useActionRunSettings(action, settingsStore)
    const runStatus = useActionRunSelector(action.id, assignmentContext, (run) => run?.status ?? 'idle')
    const agentActive = useActionRunSelector(action.id, assignmentContext, (run) => {
        const active = run?.status === 'queued' || run?.status === 'running' || run?.status === 'waitingForInput'

        return !!active && run?.activeActionType === 'agent'
    })
    const interactionReady = useActionRunSelector(action.id, assignmentContext, (run) => !!run?.interactionReady)
    const hasApprovals = useActionRunSelector(action.id, assignmentContext, (run) => !!run?.approvals.length)
    const hasQuestion = useActionRunSelector(action.id, assignmentContext, (run) => !!run?.question)
    const promptDraft = currentActionPromptDraft(action, assignmentContext, action.type === 'agent')
    const prompt = useSyncExternalStore(promptDraft.subscribe, promptDraft.getSnapshot, promptDraft.getSnapshot)
    const editorSnapshot = useSyncExternalStore(
        promptDraft.subscribeEditor,
        promptDraft.getEditorSnapshot,
        promptDraft.getEditorSnapshot,
    )
    const conversationSnapshot = useSyncExternalStore(
        conversationStore.subscribe,
        conversationStore.getSnapshot,
        conversationStore.getSnapshot,
    )
    const sessionActive = runStatus === 'queued' || runStatus === 'running' || runStatus === 'waitingForInput'
    const orphanWaiting = !sessionActive && conversationSnapshot.selectedConversation?.status === 'waitingForInput'
    const running = runStatus === 'queued' || runStatus === 'running'
    const waitingForAgentInput = (runStatus === 'waitingForInput' && agentActive) || orphanWaiting
    const promptHasText = prompt.trim().length > 0
    const showStop = running || (runStatus === 'waitingForInput' && !agentActive)
    const showFinish = waitingForAgentInput
    const showSchedule = (!sessionActive && !orphanWaiting) || (waitingForAgentInput && promptHasText)
    const showAgentSend = (!sessionActive && !orphanWaiting && action.type === 'agent')
        || (waitingForAgentInput && promptHasText)
    const showCommandRun = !sessionActive && !orphanWaiting && action.type === 'command'
    const runState = {
        agentActive,
        hasApprovals,
        hasQuestion,
        interactionReady,
        runDisabledMessage: settings.runDisabledMessage,
        runStatus,
    }
    const runDisabled = actionPopupRunDisabled(
        action,
        runState,
        prompt,
        editorSnapshot.preparationStatus,
    )
    const operationInput = {
        action,
        context: assignmentContext,
        conversationStore,
        historyStore,
        inputStore,
        resultStore,
        runValidationError,
        settings,
        settingsStore,
    }

    const handlePrimaryRun = async () => {
        await runPopupAction(operationInput)
    }
    const handleCancel = () => void cancelPopupAction(action, assignmentContext, conversationStore)
    const handleFinish = () => void finishPopupAction(action, assignmentContext, conversationStore)
    const handleToggleSchedule = () => scheduleStore.toggle()

    return (
        <Box
            data-testid="action-popup-bottom-row"
            data-embedded={embedded ? 'true' : undefined}
            sx={{
                bgcolor: embedded ? 'background.paper' : 'background.default', borderColor: 'divider',
                containerType: 'inline-size', flexShrink: 0, px: embedded ? 1 : 2,
                pb: embedded ? 1 : 1.5, pt: embedded ? 0 : 1.5,
            }}
        >
            <Box
                data-footer-layout
                sx={{
                    alignItems: 'center', display: 'flex', gap: 1, justifyContent: 'space-between', minWidth: 0, width: '100%',
                    '@container (max-width: 420px)': {
                        '& [data-footer-selectors]': { minWidth: 0 },
                        '& [data-footer-usage]': { minWidth: 0 },
                    },
                }}
            >
                <Box data-footer-selectors sx={{ flexShrink: 1, minWidth: 158, overflow: 'hidden' }}>
                    {action.type === 'agent' ? (
                        <ActionAgentSelectors action={action} context={assignmentContext} settingsStore={settingsStore} />
                    ) : null}
                </Box>
                <Box data-footer-usage sx={{ display: 'flex', flexShrink: 1, justifyContent: 'center', minWidth: 235, overflow: 'hidden' }}>
                    <ActionUsageSummaryOwner
                        action={action}
                        context={assignmentContext}
                        conversationStore={conversationStore}
                        historyStore={historyStore}
                        scopeStore={usageScopeStore}
                    />
                </Box>
                <Box
                    data-footer-controls
                    sx={{ alignItems: 'center', display: 'flex', flexShrink: 0, gap: 1, justifyContent: 'flex-end', minWidth: 64 }}
                >
                    {showFinish ? (
                        <ActionPopupFinishButton
                            disabled={!settings.backendAvailable || (sessionActive && !interactionReady)}
                            onFinish={handleFinish}
                            onStop={handleCancel}
                        />
                    ) : null}
                    {showSchedule ? (
                        <Tooltip title="Schedule">
                            <span>
                                <IconButton
                                    aria-label="Schedule"
                                    disabled={!settings.backendAvailable}
                                    onClick={handleToggleSchedule}
                                    size="small"
                                >
                                    <CalendarOutline sx={{ fontSize: 18 }} />
                                </IconButton>
                            </span>
                        </Tooltip>
                    ) : null}
                    {showAgentSend ? (
                        <Tooltip title="Send">
                            <span>
                                <IconButton aria-label="Send" color="primary" disabled={runDisabled} onClick={handlePrimaryRun} size="small">
                                    <ArrowUpwardOutlined sx={{ fontSize: 18 }} />
                                </IconButton>
                            </span>
                        </Tooltip>
                    ) : showCommandRun ? (
                        <Tooltip title="Run">
                            <Button
                                disabled={runDisabled}
                                onClick={handlePrimaryRun}
                                size="small"
                                startIcon={<Play sx={{ fontSize: '13px !important' }} />}
                                sx={{ height: 34, px: 2 }}
                                variant="contained"
                            >
                                Run
                            </Button>
                        </Tooltip>
                    ) : showStop ? (
                        <Tooltip title="Stop">
                            <span>
                                <IconButton aria-label="Stop" disabled={!settings.backendAvailable} onClick={handleCancel} size="small">
                                    <StopOutlined sx={{ fontSize: 18 }} />
                                </IconButton>
                            </span>
                        </Tooltip>
                    ) : null}
                </Box>
            </Box>
        </Box>
    )
}

/** Returns displayed conversation context occupancy as a whole-number percentage. */
export function contextWindowUsedPercent(contextWindowUsage: unknown) {
    if (!contextWindowUsage || typeof contextWindowUsage !== 'object' || Array.isArray(contextWindowUsage)) return null
    const { capacityTokens, usedTokens } = contextWindowUsage as Record<string, unknown>
    if (!Number.isSafeInteger(usedTokens) || (usedTokens as number) < 0) return null
    if (!Number.isSafeInteger(capacityTokens) || (capacityTokens as number) <= 0) return null

    return Math.min(100, Math.round((usedTokens as number) / (capacityTokens as number) * 100))
}

import { useEffect, useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../data/action_context'
import { cardPopupService, subscribeCardPopups } from '../../../services/card_popup_service'
import { agentAcknowledgementService } from '../../../services/agents/agent_acknowledgement_service'
import { useActionRunSelector } from '../../hooks/use_action_runs'
import { ActionConversationChat } from './action_conversation_chat'
import type { ActionConversationStore } from './action_conversation_store'

interface ActionConversationChatOwnerProps {
    actionId: string
    context: ActionContext
    popupEntryId?: string
    store: ActionConversationStore
}

/** Subscribes chat boundary to selected conversation, scoped acknowledgement, and popup stacking. */
export function ActionConversationChatOwner(props: ActionConversationChatOwnerProps) {
    const { actionId, context, popupEntryId, store } = props
    const liveConversation = useActionRunSelector(actionId, context, (run) => run?.conversation ?? null)
    const runStatus = useActionRunSelector(actionId, context, (run) => run?.status ?? 'idle')
    const { selectedConversation } = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
    const popupEntries = useSyncExternalStore(
        subscribeCardPopups,
        () => cardPopupService.getSnapshot(),
        () => cardPopupService.getSnapshot(),
    )
    const cardInternalId = context.cardInternalId
    const conversation = liveConversation ?? selectedConversation
    const status = runStatus === 'idle' && conversation?.status === 'waitingForInput' ? 'waitingForInput' : runStatus
    const visible = !!popupEntryId && popupEntries.at(-1)?.id === popupEntryId && !!cardInternalId && !!conversation

    useEffect(() => {
        if (!popupEntryId || !cardInternalId || !conversation) return undefined

        agentAcknowledgementService.setConversationVisible(popupEntryId, cardInternalId, actionId, conversation, visible)

        return () => agentAcknowledgementService.setConversationVisible(
            popupEntryId,
            cardInternalId,
            actionId,
            conversation,
            false,
        )
    }, [actionId, cardInternalId, conversation, popupEntryId, visible])

    return <ActionConversationChat conversation={conversation} status={status} />
}

import { useEffect, useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import type { ActionConversationStore } from '../../conversation/action_conversation_store'
import type { ActionHistoryStore } from '../state/action_history_store'
import { useActionRunSelector } from '../../../hooks/use_action_runs'
import { ActionUsageSummary } from './action_usage_summary'
import type { ActionUsageScopeStore } from './action_usage_scope_store'

interface ActionUsageSummaryOwnerProps {
    action: ActionDefinition
    context: ActionContext
    conversationStore: ActionConversationStore
    historyStore: ActionHistoryStore
    scopeStore: ActionUsageScopeStore
}

/** Subscribes usage summary to conversation and history data only. */
export function ActionUsageSummaryOwner(props: ActionUsageSummaryOwnerProps) {
    const { action, context, conversationStore, historyStore, scopeStore } = props
    const liveConversation = useActionRunSelector(action.id, context, (run) => run?.conversation ?? null)
    const conversationSnapshot = useSyncExternalStore(
        conversationStore.subscribe,
        conversationStore.getSnapshot,
        conversationStore.getSnapshot,
    )
    const historySnapshot = useSyncExternalStore(historyStore.subscribe, historyStore.getSnapshot, historyStore.getSnapshot)
    const scopeSnapshot = useSyncExternalStore(scopeStore.subscribe, scopeStore.getSnapshot, scopeStore.getSnapshot)
    const displayedConversation = liveConversation ?? conversationSnapshot.selectedConversation
    const scope = displayedConversation ? scopeSnapshot : 'actionCard'

    useEffect(() => {
        void historyStore.load()
    }, [historyStore])

    useEffect(() => {
        if (!displayedConversation) scopeStore.useActionCardScope()
    }, [displayedConversation, scopeStore])

    if (context.kind !== 'card' || !context.file || !context.cardInternalId || action.type !== 'agent') return null

    const handleToggleScope = () => scopeStore.toggle(!!displayedConversation)

    return (
        <ActionUsageSummary
            actionId={action.id}
            cardInternalId={context.cardInternalId}
            conversation={displayedConversation}
            conversations={conversationStore.conversationOptions(liveConversation)}
            history={historySnapshot.entries}
            liveConversation={liveConversation}
            onToggleScope={handleToggleScope}
            scope={scope}
        />
    )
}

import { Box, ButtonBase, Stack, Tooltip, Typography, type SxProps, type Theme } from '@mui/material'
import type { ReactNode } from 'react'
import type { AgentConversation, AgentTokenUsage } from '../../../../data/data_types'
import type { ActionRunHistoryEntry, CommitReference } from '../../../../data/electron_action_bridge'
import type { AgentFileChangeUsage } from '../../../../services/agents/agent_usage'
import type { ActionUsageScope } from './action_usage_scope_store'
import { scopedActionUsage, type LineUsage } from './action_usage_summary_data'

const NUMBER_FORMAT = new Intl.NumberFormat('en-US')
const USAGE_CONTROL_SX: SxProps<Theme> = {
    borderBottom: '1px dotted',
    borderColor: 'custom.borderHover',
    borderRadius: '4px',
    color: 'text.secondary',
    cursor: 'pointer',
    fontSize: 'caption.fontSize',
    lineHeight: 'caption.lineHeight',
    px: 0.25,
    '&:hover': { bgcolor: 'custom.track', color: 'primary.main' },
    '&.Mui-focusVisible': {
        boxShadow: (theme) => `0 0 0 3px ${theme.palette.custom.primaryBg}`,
        color: 'primary.main',
        outline: '1px solid',
        outlineColor: 'primary.main',
    },
}

interface ActionUsageSummaryProps {
    actionId: string
    cardInternalId: string
    conversation: AgentConversation | null
    conversations: AgentConversation[]
    history: ActionRunHistoryEntry[]
    liveConversation: AgentConversation | null
    onToggleScope: () => void
    scope: ActionUsageScope
}

function commitLine(commit: CommitReference) {
    return `${commit.commit.slice(0, 7)}: +${NUMBER_FORMAT.format(commit.insertions)} / -${NUMBER_FORMAT.format(commit.deletions)}`
}

function scopeName(scope: ActionUsageScope) {
    return scope === 'conversation' ? 'Conversation' : 'Action/card'
}

function scopeTooltip(
    definition: string,
    conversationValue: string | null,
    actionCardValue: string,
    scope: ActionUsageScope,
    activeDetails?: ReactNode,
) {
    const switchTarget = scope === 'conversation' ? 'Action/card' : 'Conversation'
    const interactionExplanation = conversationValue === null
        ? 'Conversation unavailable; clicking keeps Action/card scope.'
        : `Click to switch to ${switchTarget}.`

    return (
        <Stack spacing={0.5}>
            <Typography color="inherit" variant="caption">{definition}</Typography>
            <Typography color="inherit" variant="caption">
                Active scope: {scopeName(scope)}. {interactionExplanation}
            </Typography>
            <Typography color="inherit" variant="caption">
                Conversation{scope === 'conversation' ? ' (active)' : ''}: {conversationValue ?? 'unavailable'}
            </Typography>
            <Typography color="inherit" variant="caption">
                Action/card{scope === 'actionCard' ? ' (active)' : ''}: {actionCardValue}
            </Typography>
            {activeDetails}
        </Stack>
    )
}

function tokenValue(usage: AgentTokenUsage) {
    return `${NUMBER_FORMAT.format(usage.totalTokens)} tokens`
}

function changeValue(usage: AgentFileChangeUsage) {
    return `+${NUMBER_FORMAT.format(usage.insertions)} / -${NUMBER_FORMAT.format(usage.deletions)}`
}

function lineValue(usage: LineUsage) {
    return `${NUMBER_FORMAT.format(usage.insertions + usage.deletions)} lines`
}

/** Three shared-scope usage controls for one agent action on one card. */
export function ActionUsageSummary(props: ActionUsageSummaryProps) {
    const { actionId, cardInternalId, conversation, conversations, history, liveConversation, onToggleScope, scope } = props
    const scopedUsage = scopedActionUsage(
        conversations,
        liveConversation,
        conversation,
        history,
        actionId,
        cardInternalId,
    )
    const conversationUsage = scopedUsage.conversation
    const activeScope: ActionUsageScope = scope === 'conversation' && conversationUsage ? 'conversation' : 'actionCard'
    const activeUsage = activeScope === 'conversation' && conversationUsage
        ? conversationUsage
        : scopedUsage.actionCard
    const activeLines = activeUsage.lines
    const hasChanges = activeUsage.changes.insertions + activeUsage.changes.deletions > 0
    const totalLines = activeLines.insertions + activeLines.deletions
    const lineDetails = (
        <>
            <Typography color="inherit" variant="caption">
                files changed: {NUMBER_FORMAT.format(activeLines.filesChanged)}, insertions: {NUMBER_FORMAT.format(activeLines.insertions)},
                {' '}deletions: {NUMBER_FORMAT.format(activeLines.deletions)}
            </Typography>
            {activeLines.commits.map((commit, index) => (
                <Typography color="inherit" key={`${commit.repositoryRoot}\u0000${commit.commit}\u0000${index}`} variant="caption">
                    {commitLine(commit)}
                </Typography>
            ))}
        </>
    )
    const activeScopeName = scopeName(activeScope)
    return (
        <Box
            sx={{
                alignItems: 'center', display: 'flex', flexWrap: 'wrap', gap: 1, minWidth: 0,
                '@container (max-width: 420px)': { flexWrap: 'nowrap', gap: 0.5 },
            }}
        >
            <Tooltip describeChild title={scopeTooltip(
                'Tokens are cumulative provider token usage.',
                scopedUsage.conversation ? tokenValue(scopedUsage.conversation.tokens) : null,
                tokenValue(scopedUsage.actionCard.tokens),
                activeScope,
            )}>
                <ButtonBase
                    aria-label={`Tokens, ${activeScopeName} scope`}
                    onClick={onToggleScope}
                    sx={USAGE_CONTROL_SX}
                >
                    <Box
                        component="span"
                        data-usage-prefix
                        sx={{ '@container (max-width: 420px)': { display: 'none' } }}
                    >
                        tokens:{' '}
                    </Box>
                    {NUMBER_FORMAT.format(activeUsage.tokens.totalTokens)}
                </ButtonBase>
            </Tooltip>
            {hasChanges ? (
                <Tooltip describeChild title={scopeTooltip(
                    'Changes are additions and deletions across completed provider file-change patches.',
                    scopedUsage.conversation ? changeValue(scopedUsage.conversation.changes) : null,
                    changeValue(scopedUsage.actionCard.changes),
                    activeScope,
                )}>
                    <ButtonBase
                        aria-label={`Changes, ${activeScopeName} scope`}
                        onClick={onToggleScope}
                        sx={USAGE_CONTROL_SX}
                    >
                        <Box
                            component="span"
                            data-usage-prefix
                            sx={{ '@container (max-width: 420px)': { display: 'none' } }}
                        >
                            changes:&nbsp;
                        </Box>
                        <Box component="span" sx={{ color: 'success.main' }}>
                            +{NUMBER_FORMAT.format(activeUsage.changes.insertions)}
                        </Box>
                        &nbsp;/&nbsp;
                        <Box component="span" sx={{ color: 'error.main' }}>
                            -{NUMBER_FORMAT.format(activeUsage.changes.deletions)}
                        </Box>
                    </ButtonBase>
                </Tooltip>
            ) : null}
            {totalLines > 0 ? (
                <Tooltip describeChild title={scopeTooltip(
                    'Lines are additions plus deletions in captured Git commit diffs.',
                    scopedUsage.conversation ? lineValue(scopedUsage.conversation.lines) : null,
                    lineValue(scopedUsage.actionCard.lines),
                    activeScope,
                    lineDetails,
                )}>
                    <ButtonBase
                        aria-label={`Lines, ${activeScopeName} scope`}
                        onClick={onToggleScope}
                        sx={USAGE_CONTROL_SX}
                    >
                        <Box
                            component="span"
                            data-usage-prefix
                            sx={{ '@container (max-width: 420px)': { display: 'none' } }}
                        >
                            lines:{' '}
                        </Box>
                        {NUMBER_FORMAT.format(totalLines)}
                    </ButtonBase>
                </Tooltip>
            ) : null}
        </Box>
    )
}

const {
    accumulateUsage,
    createProviderEventEntry,
    createEventEntry,
    updateProviderSession,
} = require('./agent_conversation');
const { emitRunEvent, hasPendingInteraction } = require('./agent_run_state');
const {
    appendAssistantOutput,
    appendDiagnosticContent,
    completeAssistantOutput,
    lastMessageEntry,
    nextRunSequence,
    replaceAssistantOutput,
    startAssistantItem,
} = require('./agent_run_transcript');
const { redactConversationEvent, redactSecrets } = require('./agent_secret_redaction');
const { requireString } = require('./agent_run_validation');

function handleSessionStarted(service, run, event) {
    run.providerConversationId = event.conversationId;
}

function handleTurnStarted(service, run) {
    run.assistantItemIndex = 0;
    run.assistantItems.clear();
    run.currentAssistantMessageId = null;
    run.liveTurnUsage = null;
    run.turnStarted = true;
}

function handleUsage(service, run, event) {
    run.liveTurnUsage = event.usage;
    const usage = accumulateUsage(run.conversation.usage, event.usage);
    emitRunEvent(run, { type: 'usage', usage });
}

function handleAssistantStarted(service, run, event, timestamp) {
    const item = startAssistantItem(run, requireString(event.itemId, 'assistant item id'), timestamp);
    emitRunEvent(run, { content: '', messageId: item.messageId, sequence: item.sequence, type: 'output' });
}

function handleAssistant(service, run, event, timestamp) {
    const safeContent = redactSecrets(event.content, run.secretValues);
    const itemId = run.agent === 'codex'
        ? requireString(event.itemId, 'assistant item id')
        : event.itemId;
    const { message, segment } = appendAssistantOutput(run, safeContent, timestamp, itemId);
    if (segment.length > 0) {
        emitRunEvent(run, { content: segment, messageId: message.id, sequence: message.sequence, type: 'output' });
    }
}

function handleAssistantCompleted(service, run, event, timestamp) {
    const safeContent = redactSecrets(event.content, run.secretValues);
    const itemId = requireString(event.itemId, 'assistant item id');
    const { message, previousContent, replaced } = replaceAssistantOutput(run, safeContent, timestamp, itemId);
    if (!replaced) return;

    emitRunEvent(run, {
        content: safeContent,
        messageId: message.id,
        previousContent,
        replace: true,
        sequence: message.sequence,
        type: 'output',
    });
}

function handleChangedPaths(service, run, event) {
    event.paths.forEach((filePath) => run.changedPaths.add(filePath));
}

/** Provider events are keyed by `providerItemId` so a later revision of the same item replaces its entry. */
function handleEvent(service, run, event, timestamp) {
    const safeEvent = redactConversationEvent(event.event, run.secretValues);
    const providerItemId = requireString(safeEvent.providerItemId, 'event providerItemId');
    const currentIndex = run.providerEventEntryIndexes.get(providerItemId);
    let eventEntry;
    if (currentIndex !== undefined) {
        const current = run.conversation.entries[currentIndex];
        eventEntry = createProviderEventEntry(safeEvent, current.id, timestamp, current.sequence);
        run.conversation.entries[currentIndex] = eventEntry;
    } else {
        const previousEntry = run.conversation.entries.at(-1);
        if (safeEvent.type === 'diagnostic' && previousEntry?.kind === 'event' && previousEntry.type === 'diagnostic') {
            eventEntry = appendDiagnosticContent(previousEntry, safeEvent.content);
            run.conversation.entries[run.conversation.entries.length - 1] = eventEntry;
        } else {
            const sequence = nextRunSequence(run);
            eventEntry = createProviderEventEntry(
                safeEvent,
                `${run.id}-event-${sequence}`,
                timestamp,
                sequence,
            );
            run.providerEventEntryIndexes.set(providerItemId, run.conversation.entries.length);
            run.conversation.entries.push(eventEntry);
        }
    }
    emitRunEvent(run, { event: eventEntry, type: 'agentEvent' });
}

function handleTranscript(service, run, event, timestamp) {
    const safeContent = redactSecrets(event.content, run.secretValues);
    run.conversation.entries.push(createEventEntry(
        `${run.id}-provider-${run.conversation.entries.length}`,
        event.toolType,
        safeContent,
        timestamp,
        nextRunSequence(run),
    ));
}

function handleError(service, run, event) {
    service.recordOutput(run.id, 'stderr', event.content);
}

function handleFatal(service, run, event) {
    service.failStreamingRun(run, new Error(event.content));
}

function handleSessionFailed(service, run, event) {
    run.missingSession = event.missingSession;
    service.failStreamingRun(run, new Error(event.content));
}

async function handleQuestion(service, run, event) {
    run.conversation.status = 'waitingForInput';
    run.waitingForQuestion = true;
    run.pendingQuestions = event.questions;
    await service.persistCheckpoint(run);
    emitRunEvent(run, { questions: event.questions, requestId: event.requestId, state: 'waitingForInput', type: 'question' });
}

async function handleApproval(service, run, event) {
    const requestId = event.approval.requestId;
    if (run.pendingApprovals.has(requestId)) throw new Error(`Duplicate agent approval request id: ${requestId}`);
    run.pendingApprovals.set(requestId, { ...event.approval, submitted: false });
    run.conversation.status = 'waitingForInput';
    await service.persistCheckpoint(run);
    emitRunEvent(run, { approval: event.approval, state: 'waitingForInput', type: 'approval' });
}

function handleApprovalSubmitted(service, run, event) {
    const approval = run.pendingApprovals.get(event.requestId);
    if (!approval) return;
    approval.submitted = true;
    emitRunEvent(run, { requestId: event.requestId, type: 'approvalSubmitted' });
}

function handleApprovalResolved(service, run, event) {
    if (!run.pendingApprovals.delete(event.requestId)) return;
    const state = hasPendingInteraction(run) ? 'waitingForInput' : 'running';
    run.conversation.status = state;
    emitRunEvent(run, { requestId: event.requestId, state, type: 'approvalResolved' });
    emitRunEvent(run, { state, type: 'state' });
}

/**
 * End of a streaming turn: settle the assistant message, then either shut the process down,
 * send the message queued while the turn was running, or park the run waiting for input.
 */
async function handleTurnCompleted(service, run, event, timestamp) {
    completeAssistantOutput(run, timestamp);
    run.turnActive = false;
    run.waitingForQuestion = false;
    run.pendingApprovals.clear();
    run.missingSession = run.missingSession || event.missingSession;
    if (event.missingSession) run.finishing = true;
    if (event.usage) {
        run.liveTurnUsage = event.usage;
        run.conversation.usage = accumulateUsage(run.conversation.usage, run.liveTurnUsage);
        run.liveTurnUsage = null;
    }
    if (event.contextWindowUsage !== undefined) {
        if (event.contextWindowUsage) run.conversation.contextWindowUsage = event.contextWindowUsage;
        else delete run.conversation.contextWindowUsage;
    }
    if (event.usage || event.contextWindowUsage !== undefined) {
        emitRunEvent(run, {
            ...(event.contextWindowUsage !== undefined ? { contextWindowUsage: event.contextWindowUsage } : {}),
            type: 'usage',
            usage: run.conversation.usage,
        });
    }
    if (event.error) {
        service.failStreamingRun(run, new Error(event.error));
        return;
    }
    if (run.finishing) {
        service.beginFinishShutdown(run);
        return;
    }
    if (run.queuedMessage) {
        const { content, revision } = run.queuedMessage;
        run.conversation.status = 'waitingForInput';
        await service.sendStreamingMessage(run, content);
        run.queuedMessage = null;
        run.sentQueuedMessageRevision = revision;
        return;
    }
    const synchronizedMessage = lastMessageEntry(run.conversation);
    if (synchronizedMessage) updateProviderSession(run, synchronizedMessage.id, timestamp);
    run.conversation.status = 'waitingForInput';
    run.conversation.completedAt = null;
    await service.persistCheckpoint(run);
    emitRunEvent(run, { state: 'waitingForInput', type: 'state' });
}

/** Keyed by streaming event type; unknown types are ignored. Each handler takes `(service, run, event, timestamp)`. */
const STREAMING_EVENT_HANDLERS = {
    approval: handleApproval,
    approvalResolved: handleApprovalResolved,
    approvalSubmitted: handleApprovalSubmitted,
    assistant: handleAssistant,
    assistantCompleted: handleAssistantCompleted,
    assistantStarted: handleAssistantStarted,
    changedPaths: handleChangedPaths,
    error: handleError,
    event: handleEvent,
    fatal: handleFatal,
    question: handleQuestion,
    sessionFailed: handleSessionFailed,
    sessionStarted: handleSessionStarted,
    transcript: handleTranscript,
    turnCompleted: handleTurnCompleted,
    turnStarted: handleTurnStarted,
    usage: handleUsage,
};

module.exports = { STREAMING_EVENT_HANDLERS };

