const { normalizeAgentTokenUsage } = require('../../../../shared/agent_usage_math.mjs');
const { ClaudeStreamingAdapter } = require('./agent_claude_streaming_adapter');
const { codexChangedPaths } = require('./agent_codex_events');
const { diagnosticEvent, normalizeCodexEvent, systemEvent } = require('./agent_codex_event');
const { isMissingSession } = require('./agent_provider_protocol');

const CODEX_CLIENT_NAME = 'md2';
const CODEX_CLIENT_VERSION = '1';
const CODEX_MISSING_THREAD_ERROR_CODE = -32600;
const CODEX_APPROVAL_METHODS = new Map([
    ['item/commandExecution/requestApproval', 'commandExecution'],
    ['item/fileChange/requestApproval', 'fileChange'],
]);
const CODEX_COMMAND_APPROVAL_DECISIONS = ['accept', 'acceptForSession', 'decline', 'cancel'];
const CODEX_FILE_APPROVAL_DECISIONS = ['accept', 'acceptForSession', 'decline', 'cancel'];
const CODEX_NON_EVENT_ITEM_TYPES = new Set(['agentMessage', 'hookPrompt', 'userMessage']);

function requireMessage(content) {
    if (typeof content !== 'string' || content.trim().length === 0) throw new Error('Streaming agent message is required');

    return content;
}

function codexInput(content) {
    return [{ text: requireMessage(content), type: 'text' }];
}

// The app-server already reports cache-free input tokens, unlike `codex exec`, so no subtraction here.
function codexUsage(params) {
    const usage = params.tokenUsage?.last;
    if (!usage) return null;

    return normalizeAgentTokenUsage({
        cachedInputTokens: usage.cachedInputTokens,
        inputTokens: usage.inputTokens,
        outputTokens: usage.outputTokens,
        reasoningTokens: usage.reasoningOutputTokens,
    });
}

function codexContextWindowUsage(params) {
    const usedTokens = params.tokenUsage?.last?.totalTokens;
    const capacityTokens = params.tokenUsage?.modelContextWindow;
    if (!Number.isSafeInteger(usedTokens) || usedTokens < 0) return null;
    if (!Number.isSafeInteger(capacityTokens) || capacityTokens <= 0) return null;

    return { capacityTokens, usedTokens };
}

function eventTextParts(event, field, index) {
    const parts = [...event[field]];
    while (parts.length <= index) parts.push('');

    return parts;
}

function isCodexMissingThreadError(error, providerConversationId) {
    if (!providerConversationId || error?.code !== CODEX_MISSING_THREAD_ERROR_CODE) return false;

    return error.message === `no rollout found for thread id ${providerConversationId}`;
}

function requireCodexApprovalId(value, field) {
    if (typeof value !== 'string' || value.length === 0) throw new Error(`Missing Codex approval ${field}`);

    return value;
}

function sameDecision(left, right) {
    return JSON.stringify(left) === JSON.stringify(right);
}

function availableApprovalDecisions(approval) {
    if (approval.kind === 'fileChange') return CODEX_FILE_APPROVAL_DECISIONS;
    if (Array.isArray(approval.availableDecisions)) return approval.availableDecisions;

    return CODEX_COMMAND_APPROVAL_DECISIONS;
}

class CodexStreamingAdapter {
    constructor(writeLine, onEvent, rootPath, providerConversationId, onRuntimeEvent) {
        this.writeLine = writeLine;
        this.onEvent = onEvent;
        this.onRuntimeEvent = onRuntimeEvent;
        this.providerConversationId = providerConversationId;
        this.rootPath = rootPath;
        this.activeTurnId = null;
        this.activeItems = new Map();
        this.assistantItemOrder = [];
        this.assistantStreams = new Map();
        this.completedItemIds = new Set();
        this.diagnosticSequence = 1;
        this.initialPrompt = null;
        this.nextRequestId = 1;
        this.pendingRequests = new Map();
        this.pendingApprovals = new Map();
        this.threadId = null;
        this.turnContextWindowUsage = undefined;
        this.turnUsage = null;
    }

    async start(prompt) {
        this.initialPrompt = requireMessage(prompt);
        await this.sendRequest('initialize', {
            capabilities: { experimentalApi: true },
            clientInfo: { name: CODEX_CLIENT_NAME, version: CODEX_CLIENT_VERSION },
        }, 'initialize');
    }

    async sendMessage(content) {
        const input = codexInput(content);
        if (!this.threadId) throw new Error('Codex streaming thread is not ready');
        if (this.activeTurnId) {
            await this.sendRequest('turn/steer', {
                expectedTurnId: this.activeTurnId,
                input,
                threadId: this.threadId,
            });
            return;
        }
        await this.sendRequest('turn/start', { input, threadId: this.threadId });
    }

    async answerQuestion(requestId, answers) {
        if (requestId === null || requestId === undefined) throw new Error('Missing Codex question request id');
        const normalizedAnswers = Object.fromEntries(Object.entries(answers).map(([questionId, answer]) => [
            questionId,
            { answers: Array.isArray(answer) ? answer : [answer] },
        ]));
        await this.writeLine({ id: requestId, result: { answers: normalizedAnswers } });
    }

    async answerApproval(requestId, decision) {
        const pendingApproval = this.pendingApprovals.get(requestId);
        if (!pendingApproval) throw new Error(`Unknown or stale Codex approval request id: ${requestId}`);
        if (pendingApproval.submitted) throw new Error(`Codex approval request was already submitted: ${requestId}`);
        const availableDecisions = availableApprovalDecisions(pendingApproval.approval);
        if (!availableDecisions.some((availableDecision) => sameDecision(availableDecision, decision))) {
            throw new Error(`Unsupported Codex approval decision for request ${requestId}`);
        }
        pendingApproval.submitted = true;
        try {
            await this.writeLine({ id: requestId, result: { decision } });
        } catch (error) {
            pendingApproval.submitted = false;
            throw error;
        }
        await this.onEvent({ requestId, type: 'approvalSubmitted' });
    }

    async sendRequest(method, params, purpose = null) {
        const id = this.nextRequestId;
        this.nextRequestId += 1;
        if (purpose) this.pendingRequests.set(id, purpose);
        try {
            await this.writeLine({ id, method, params });
        } catch (error) {
            this.pendingRequests.delete(id);
            throw error;
        }
    }

    async handleMessage(message) {
        if (Object.hasOwn(message, 'id') && !message.method) {
            await this.handleResponse(message);
            return;
        }
        if (message.method === 'item/tool/requestUserInput') {
            await this.onEvent({ questions: message.params.questions, requestId: message.id, type: 'question' });
            return;
        }
        if (CODEX_APPROVAL_METHODS.has(message.method)) {
            await this.handleApprovalRequest(message);
            return;
        }
        await this.handleNotification(message.method, message.params ?? {});
    }

    async handleApprovalRequest(message) {
        if (message.id === null || message.id === undefined) throw new Error('Missing Codex approval request id');
        if (this.pendingApprovals.has(message.id)) throw new Error(`Duplicate Codex approval request id: ${message.id}`);
        const kind = CODEX_APPROVAL_METHODS.get(message.method);
        const params = message.params;
        if (!params || typeof params !== 'object' || Array.isArray(params)) throw new Error('Missing Codex approval params');
        const threadId = requireCodexApprovalId(params.threadId, 'thread id');
        const turnId = requireCodexApprovalId(params.turnId, 'turn id');
        const itemId = requireCodexApprovalId(params.itemId, 'item id');
        if (threadId !== this.threadId) throw new Error(`Mismatched Codex approval thread id: ${threadId}`);
        if (turnId !== this.activeTurnId) throw new Error(`Mismatched Codex approval turn id: ${turnId}`);
        const trackedItem = this.activeItems.get(itemId);
        if (!trackedItem || trackedItem.itemType !== kind || this.completedItemIds.has(itemId)) {
            throw new Error(`Mismatched Codex approval item id: ${itemId}`);
        }
        const filePaths = kind === 'fileChange'
            ? trackedItem.item.changes
                ?.filter(({ path }) => typeof path === 'string' && path.length > 0)
                .map(({ path }) => path) ?? []
            : [];
        const approval = { ...params, filePaths, kind, provider: 'codex', requestId: message.id };
        this.pendingApprovals.set(message.id, { approval, submitted: false });
        await this.onEvent({ approval, type: 'approval' });
    }

    async handleResponse(message) {
        const purpose = this.pendingRequests.get(message.id);
        if (!purpose) {
            if (message.error) await this.onEvent({ content: message.error.message ?? 'Codex request failed', type: 'fatal' });
            return;
        }
        this.pendingRequests.delete(message.id);
        if (message.error) {
            const content = message.error.message ?? `Codex ${purpose} failed`;
            if (purpose === 'rateLimitsRead') {
                await this.onRuntimeEvent({ kind: 'unavailable', observedAt: Date.now() });
                return;
            }
            if (purpose === 'threadResume') {
                const missingSession = isCodexMissingThreadError(message.error, this.providerConversationId)
                    || isMissingSession('codex', { error: message.error, type: 'error' }, false);
                await this.onEvent({ content, missingSession, type: 'sessionFailed' });
                return;
            }
            await this.onEvent({ content, type: 'fatal' });
            return;
        }
        if (purpose === 'initialize') {
            await this.writeLine({ method: 'initialized', params: {} });
            await this.sendRequest('account/rateLimits/read', undefined, 'rateLimitsRead');
            if (this.providerConversationId) {
                await this.sendRequest('thread/resume', {
                    cwd: this.rootPath,
                    threadId: this.providerConversationId,
                }, 'threadResume');
                return;
            }
            await this.sendRequest('thread/start', { cwd: this.rootPath }, 'threadStart');
            return;
        }
        if (purpose === 'threadStart' || purpose === 'threadResume') {
            this.threadId = message.result?.thread?.id ?? message.result?.threadId ?? this.providerConversationId;
            if (!this.threadId) throw new Error('Codex app-server did not return a thread id');
            await this.onEvent({ conversationId: this.threadId, type: 'sessionStarted' });
            await this.sendMessage(this.initialPrompt);
            return;
        }
        if (purpose === 'rateLimitsRead') {
            const hasSingleBucket = !!message.result?.rateLimits && typeof message.result.rateLimits === 'object';
            const hasBuckets = !!message.result?.rateLimitsByLimitId
                && typeof message.result.rateLimitsByLimitId === 'object'
                && Object.keys(message.result.rateLimitsByLimitId).length > 0;
            await this.onRuntimeEvent(hasSingleBucket || hasBuckets
                ? { kind: 'snapshot', observedAt: Date.now(), payload: message.result }
                : { kind: 'unavailable', observedAt: Date.now() });
        }
    }

    async handleNotification(method, params) {
        if (method === 'turn/started') {
            this.activeItems.clear();
            this.assistantItemOrder = [];
            this.assistantStreams.clear();
            this.completedItemIds.clear();
            this.turnContextWindowUsage = undefined;
            this.activeTurnId = params.turn?.id ?? params.turnId;
            await this.onEvent({ turnId: this.activeTurnId, type: 'turnStarted' });
            return;
        }
        if (method === 'serverRequest/resolved') {
            await this.handleApprovalResolved(params);
            return;
        }
        if (method === 'item/started') {
            await this.handleItemStarted(method, params.item);
            return;
        }
        if (method === 'item/agentMessage/delta') {
            const trackedItem = await this.requireActiveItem(method, params.itemId, 'agentMessage');
            if (!trackedItem) return;
            trackedItem.assistantText = trackedItem.assistantText || params.delta.length > 0;
            trackedItem.bufferedAssistantText += params.delta;
            await this.flushAssistantStreams();
            return;
        }
        if (method === 'item/reasoning/summaryTextDelta') {
            await this.handleReasoningDelta(method, params, 'summary', params.summaryIndex);
            return;
        }
        if (method === 'item/reasoning/summaryPartAdded') {
            const trackedItem = await this.requireActiveItem(method, params.itemId, 'reasoning');
            if (!trackedItem) return;
            trackedItem.event = {
                ...trackedItem.event,
                summary: eventTextParts(trackedItem.event, 'summary', params.summaryIndex),
            };
            await this.emitEvent(trackedItem.event);
            return;
        }
        if (method === 'item/reasoning/textDelta') {
            await this.handleReasoningDelta(method, params, 'details', params.contentIndex);
            return;
        }
        if (method === 'item/commandExecution/outputDelta') {
            const trackedItem = await this.requireActiveItem(method, params.itemId, 'commandExecution');
            if (!trackedItem) return;
            trackedItem.event = { ...trackedItem.event, content: `${trackedItem.event.content}${params.delta}` };
            await this.emitEvent(trackedItem.event);
            return;
        }
        if (method === 'item/plan/delta') {
            const trackedItem = await this.requireActiveItem(method, params.itemId, 'plan');
            if (!trackedItem) return;
            trackedItem.event = { ...trackedItem.event, content: `${trackedItem.event.content}${params.delta}` };
            await this.emitEvent(trackedItem.event);
            return;
        }
        if (method === 'thread/tokenUsage/updated') {
            const usage = codexUsage(params);
            if (!usage) return;
            this.turnContextWindowUsage = codexContextWindowUsage(params);
            this.turnUsage = usage;
            await this.onEvent({ type: 'usage', usage });
            return;
        }
        if (method === 'account/rateLimits/updated') {
            await this.onRuntimeEvent({ kind: 'update', observedAt: Date.now(), payload: params });
            return;
        }
        if (method === 'item/completed') {
            await this.handleItemCompleted(method, params.item);
            return;
        }
        const normalizedSystemEvent = systemEvent(method, params);
        if (normalizedSystemEvent) {
            await this.emitEvent(normalizedSystemEvent);
            return;
        }
        if (method === 'error') {
            const content = params.error?.message ?? 'Codex turn failed';
            await this.emitEvent({
                content,
                label: 'Turn failure',
                providerItemId: `system:${this.activeTurnId ?? 'unknown-turn'}:error`,
                status: 'failed',
                type: 'system',
            });
            await this.onEvent({ content, type: 'fatal' });
            return;
        }
        if (method === 'turn/completed') {
            const error = params.turn?.status === 'failed'
                ? params.turn.error?.message ?? 'Codex turn failed'
                : null;
            if (error) {
                await this.emitEvent({
                    content: error,
                    label: 'Turn failure',
                    providerItemId: `system:${params.turn?.id ?? this.activeTurnId ?? 'unknown-turn'}:turn/completed`,
                    status: 'failed',
                    type: 'system',
                });
            }
            const completedTurnId = params.turn?.id ?? this.activeTurnId;
            await this.resolveApprovalsForTurn(completedTurnId);
            this.activeTurnId = null;
            const contextWindowUsage = this.turnContextWindowUsage;
            await this.onEvent({
                ...(contextWindowUsage !== undefined ? { contextWindowUsage } : {}),
                error,
                type: 'turnCompleted',
                usage: this.turnUsage,
            });
            this.turnContextWindowUsage = undefined;
            this.turnUsage = null;
            return;
        }
        if (method?.startsWith('item/') && typeof params.itemId === 'string') {
            await this.emitDiagnostic(method, null, params.itemId);
        }
    }

    async handleApprovalResolved(params) {
        const pendingApproval = this.pendingApprovals.get(params.requestId);
        if (!pendingApproval) return;
        if (params.threadId !== pendingApproval.approval.threadId) {
            throw new Error(`Mismatched Codex approval resolution thread id: ${params.threadId}`);
        }
        this.pendingApprovals.delete(params.requestId);
        await this.onEvent({ requestId: params.requestId, type: 'approvalResolved' });
    }

    async resolveApprovalsForTurn(turnId) {
        for (const [requestId, pendingApproval] of this.pendingApprovals) {
            if (pendingApproval.approval.turnId !== turnId) continue;
            this.pendingApprovals.delete(requestId);
            await this.onEvent({ requestId, type: 'approvalResolved' });
        }
    }

    async handleItemStarted(method, item) {
        if (!item || typeof item.id !== 'string' || typeof item.type !== 'string') {
            await this.emitDiagnostic(method, item?.type, item?.id);
            return;
        }
        if (this.activeItems.has(item.id) || this.completedItemIds.has(item.id)) {
            await this.emitDiagnostic(method, item.type, item.id);
            return;
        }
        const event = normalizeCodexEvent(item, 'inProgress');
        const knownNonEvent = CODEX_NON_EVENT_ITEM_TYPES.has(item.type);
        const trackedItem = {
            event,
            assistantCompleted: false,
            assistantText: false,
            bufferedAssistantText: '',
            item,
            itemType: item.type,
        };
        this.activeItems.set(item.id, trackedItem);
        if (item.type === 'agentMessage') {
            this.assistantItemOrder.push(item.id);
            this.assistantStreams.set(item.id, trackedItem);
            await this.onEvent({ itemId: item.id, type: 'assistantStarted' });
        }
        if (event) {
            await this.emitEvent(event);
            return;
        }
        if (!knownNonEvent) await this.emitDiagnostic(method, item.type, item.id);
    }

    async handleItemCompleted(method, item) {
        if (!item || typeof item.id !== 'string' || typeof item.type !== 'string') {
            await this.emitDiagnostic(method, item?.type, item?.id);
            return;
        }
        if (this.completedItemIds.has(item.id)) {
            await this.emitDiagnostic(method, item.type, item.id);
            return;
        }
        const trackedItem = this.activeItems.get(item.id);
        if (!trackedItem) await this.emitDiagnostic(method, item.type, item.id);
        if (trackedItem && trackedItem.itemType !== item.type) {
            await this.emitDiagnostic(method, item.type, item.id);
            return;
        }
        if (item.type === 'agentMessage' && trackedItem) {
            trackedItem.assistantCompleted = true;
            await this.flushAssistantStreams();
        }
        const changedPaths = codexChangedPaths(item, this.rootPath);
        if (changedPaths.length > 0) await this.onEvent({ paths: changedPaths, type: 'changedPaths' });
        const event = normalizeCodexEvent(item, 'completed');
        if (event) await this.emitEvent(event);
        if (!event && !CODEX_NON_EVENT_ITEM_TYPES.has(item.type) && trackedItem) {
            await this.emitDiagnostic(method, item.type, item.id);
        }
        this.activeItems.delete(item.id);
        this.completedItemIds.add(item.id);
    }

    async requireActiveItem(method, itemId, expectedType) {
        const trackedItem = this.activeItems.get(itemId);
        if (!trackedItem || trackedItem.itemType !== expectedType || this.completedItemIds.has(itemId)) {
            await this.emitDiagnostic(method, expectedType, itemId);

            return null;
        }

        return trackedItem;
    }

    async handleReasoningDelta(method, params, field, index) {
        const trackedItem = await this.requireActiveItem(method, params.itemId, 'reasoning');
        if (!trackedItem || !Number.isSafeInteger(index) || index < 0) {
            if (trackedItem) await this.emitDiagnostic(method, 'reasoning', params.itemId);
            return;
        }
        const parts = eventTextParts(trackedItem.event, field, index);
        parts[index] += params.delta;
        const event = { ...trackedItem.event, [field]: parts };
        trackedItem.event = {
            ...event,
            content: event.summary.length > 0 ? event.summary.join('\n\n') : event.details.join('\n\n'),
        };
        await this.emitEvent(trackedItem.event);
    }

    async flushAssistantStreams() {
        while (this.assistantItemOrder.length > 0) {
            const itemId = this.assistantItemOrder[0];
            const stream = this.assistantStreams.get(itemId);
            if (!stream) {
                this.assistantItemOrder.shift();
                continue;
            }
            if (stream.bufferedAssistantText.length > 0) {
                const content = stream.bufferedAssistantText;
                stream.bufferedAssistantText = '';
                await this.onEvent({ content, itemId, type: 'assistant' });
            }
            if (!stream.assistantCompleted) return;
            if (stream.assistantText) await this.onEvent({ content: '\n\n', itemId, type: 'assistant' });
            this.assistantStreams.delete(itemId);
            this.assistantItemOrder.shift();
        }
    }

    async emitEvent(event) {
        await this.onEvent({ event, type: 'event' });
    }

    async emitDiagnostic(method, itemType, itemId) {
        const event = diagnosticEvent(method, itemType, itemId, this.diagnosticSequence);
        this.diagnosticSequence += 1;
        await this.emitEvent(event);
    }
}

function createAgentStreamingAdapter(
    agent,
    writeLine,
    onEvent,
    rootPath,
    providerConversationId = null,
    onRuntimeEvent = async () => undefined,
) {
    if (agent === 'claude') return new ClaudeStreamingAdapter(writeLine, onEvent, rootPath, providerConversationId);
    if (agent === 'codex') {
        return new CodexStreamingAdapter(writeLine, onEvent, rootPath, providerConversationId, onRuntimeEvent);
    }

    throw new Error(`Agent profile does not support streaming: ${agent}`);
}

module.exports = { createAgentStreamingAdapter };

const { ActionCancellationError } = require('./action_cancellation_error');
const { executeCommandAction } = require('./action_command_executor');
const { ActionPhaseError } = require('./action_phase_error');
const { runWithGitOperationContext } = require('../../git/git_operation_context');
const {
    captureCommitReferences,
    combineOutput,
    createAgentDetails,
    createCommandDetails,
} = require('./action_run_history');

function errorMessage(error, fallback) {
    return error instanceof Error ? error.message : fallback;
}

class ActionRun {
    constructor(snapshot, dependencies) {
        this.actionsFolder = snapshot.actionsFolder;
        this.activeCardsFolder = snapshot.activeCardsFolder;
        this.activityOrigin = snapshot.activityOrigin;
        this.context = snapshot.context;
        this.conversationReservation = snapshot.conversationReservation;
        this.runId = snapshot.runId;
        this.project = snapshot.project;
        this.projectFolder = snapshot.projectFolder;
        this.releasesFolder = snapshot.releasesFolder;
        this.rootAction = snapshot.rootAction;
        this.runInput = snapshot.runInput;
        this.startedAt = snapshot.startedAt;
        this.actionWorktreeRunService = dependencies.actionWorktreeRunService;
        this.agentExecutor = dependencies.agentExecutor;
        this.agentRunnerService = dependencies.agentRunnerService;
        this.commandRunner = dependencies.commandRunner;
        this.localGitService = dependencies.localGitService;
        this.publisher = dependencies.publisher;
        this.activeAction = null;
        this.activeAgentRunId = null;
        this.activeAgentQuestion = false;
        this.activeAgentApprovals = new Map();
        this.autoFinishPending = false;
        this.commitReferenceKeys = new Set();
        this.commitReferences = [];
        this.conversationIds = [];
        this.completion = null;
        this.controller = new AbortController();
        this.rootDetails = null;
        this.rootConversationId = null;
        this.nextEventSequence = 1;
    }

    start(finalize) {
        const runCompletion = this.run();
        this.completion = finalize(runCompletion);
    }

    cancel() {
        this.controller.abort();
        if (this.activeAgentRunId) this.agentRunnerService.stop(this.activeAgentRunId);
    }

    suspend() {
        this.controller.abort();
        if (this.activeAgentRunId) this.agentRunnerService.suspend(this.activeAgentRunId);
    }

    sendAgentMessage(content) {
        if (!this.activeAgentRunId) throw new Error(`Action run has no active streaming agent: ${this.runId}`);
        if (this.activeAgentQuestion) throw new Error('Answer pending structured question before sending queued prompt');
        if (this.activeAgentApprovals.size > 0) throw new Error('Answer pending approval before sending queued prompt');
        return this.agentRunnerService.sendMessage(this.activeAgentRunId, content);
    }

    beginAgentPromptDraft() {
        if (!this.activeAgentRunId) throw new Error(`Action run has no active agent: ${this.runId}`);

        return this.agentRunnerService.beginQueuedMessageDraft(this.activeAgentRunId);
    }

    setAgentQueuedMessage(sessionId, content, revision) {
        if (!this.activeAgentRunId) throw new Error(`Action run has no active agent: ${this.runId}`);

        return this.agentRunnerService.setQueuedMessage(this.activeAgentRunId, sessionId, content, revision);
    }

    sendQueuedAgentMessage(sessionId, revision) {
        if (!this.activeAgentRunId) throw new Error(`Action run has no active agent: ${this.runId}`);
        if (this.activeAgentQuestion) throw new Error('Answer pending structured question before sending queued prompt');
        if (this.activeAgentApprovals.size > 0) throw new Error('Answer pending approval before sending queued prompt');
        return this.agentRunnerService.sendQueuedMessage(this.activeAgentRunId, sessionId, revision);
    }

    async answerAgentQuestion(requestId, answers) {
        if (!this.activeAgentRunId) throw new Error(`Action run has no active streaming agent: ${this.runId}`);
        await this.agentRunnerService.answerQuestion(this.activeAgentRunId, requestId, answers);
        this.activeAgentQuestion = false;
    }

    answerAgentApproval(requestId, decision) {
        if (!this.activeAgentRunId) throw new Error(`Action run has no active streaming agent: ${this.runId}`);
        if (!this.activeAgentApprovals.has(requestId)) throw new Error(`Unknown or stale action approval request id: ${requestId}`);

        return this.agentRunnerService.answerApproval(this.activeAgentRunId, requestId, decision);
    }

    finishAgent() {
        if (!this.activeAgentRunId) throw new Error(`Action run has no active streaming agent: ${this.runId}`);
        this.agentRunnerService.finish(this.activeAgentRunId);
    }

    handleCardStateChange(cardInternalId, state) {
        if (this.context.cardInternalId !== cardInternalId) return;
        if (
            this.activeAction?.type !== 'agent'
            || !this.activeAction.streaming
            || this.activeAction.autoFinish?.state !== state
        ) return;
        if (this.activeAgentRunId) {
            this.agentRunnerService.finish(this.activeAgentRunId);
            return;
        }

        this.autoFinishPending = true;
    }

    async run() {
        return runWithGitOperationContext({ runId: this.runId }, () => this.runWithContext());
    }

    async runWithContext() {
        this.publish(this.rootAction, 'main', 'running', { type: 'run' });
        let status = 'completed';
        let failure = null;
        try {
            const onQueued = () => this.publish(this.rootAction, 'main', 'queued', { type: 'action' });
            const lockOptions = { onQueued, signal: this.controller.signal };
            await this.actionWorktreeRunService.runWithCardLock(
                this.project,
                this.context,
                () => this.runAction(this.rootAction, 'main', true),
                lockOptions,
            );
        } catch (error) {
            failure = error;
            if (error instanceof ActionCancellationError || this.controller.signal.aborted) status = 'cancelled';
            else status = error instanceof ActionPhaseError && error.rootPhase === 'after' ? 'okButNotAfter' : 'failed';
        }

        try {
            await this.persistRootActivity(status, failure);
        } catch (error) {
            failure = error;
            status = 'failed';
            const message = errorMessage(error, `${this.rootAction.label} history recording failed`);
            this.publish(this.rootAction, 'main', 'failed', { message, type: 'action' });
        }

        const result = {
            runId: this.runId,
            failure: failure ? errorMessage(failure, 'Action failed') : null,
            status,
        };
        this.publish(this.rootAction, 'main', status, { message: result.failure, type: 'run' });

        return result;
    }

    async runAction(action, phase, isRoot = false, rootPhase = phase) {
        this.throwIfCancelled();
        for (const beforeAction of action.onBefore) {
            await this.runAction(beforeAction, 'before', false, isRoot ? 'before' : rootPhase);
        }

        const output = await this.runMain(action, phase, isRoot, rootPhase);
        const matches = action.on.filter((rule) => new RegExp(rule.condition, 'u').test(output));
        for (const rule of matches) await this.runAction(rule.action, 'on', false, isRoot ? 'on' : rootPhase);

        for (const afterAction of action.onAfter) {
            await this.runAction(afterAction, 'after', false, isRoot ? 'after' : rootPhase);
        }

        return output;
    }

    async runMain(action, phase, isRoot, rootPhase) {
        this.throwIfCancelled();
        this.activeAction = action;
        this.autoFinishPending = false;

        try {
            const result = await this.executeAction(action, phase, isRoot);
            if (this.controller.signal.aborted) {
                this.publish(action, phase, 'cancelled', {
                    command: Array.isArray(result.command) ? result.command.join(' ') : result.command,
                    runWorktree: result.runWorktree,
                    message: 'Action cancelled',
                    permissionMode: result.permissionMode,
                    reference: result.reference,
                    conversationId: result.conversationId,
                    thinkingLevel: result.thinkingLevel,
                    type: 'action',
                });
                const cancellationError = new ActionCancellationError('Action cancelled');
                cancellationError.terminalEventEmitted = true;
                throw cancellationError;
            }

            const status = result.exitCode === 0 ? 'completed' : 'failed';
            const output = combineOutput(result);
            this.publish(action, phase, status, {
                command: Array.isArray(result.command) ? result.command.join(' ') : result.command,
                runWorktree: result.runWorktree,
                message: status === 'completed' ? `${action.label} completed` : `${action.label} failed with exit code ${result.exitCode}`,
                permissionMode: result.permissionMode,
                reference: result.reference,
                conversationId: result.conversationId,
                thinkingLevel: result.thinkingLevel,
                type: 'action',
            });
            this.clearActiveAction(action);
            if (result.exitCode !== 0) throw new ActionPhaseError(`${action.label} failed with exit code ${result.exitCode}`, phase, rootPhase);

            return output;
        } catch (error) {
            this.clearActiveAction(action);
            if (error instanceof ActionCancellationError || this.controller.signal.aborted) {
                if (!error?.terminalEventEmitted) this.publish(action, phase, 'cancelled', { message: 'Action cancelled', type: 'action' });
                throw new ActionCancellationError('Action cancelled');
            }
            if (error instanceof ActionPhaseError) throw error;

            const message = errorMessage(error, `${action.label} failed`);
            this.publish(action, phase, 'failed', { message, type: 'action' });
            throw new ActionPhaseError(message, phase, rootPhase, error);
        }
    }

    clearActiveAction(action) {
        if (this.activeAction !== action) return;
        this.activeAction = null;
        this.autoFinishPending = false;
    }

    async executeAction(action, phase, isRoot) {
        if (action.type === 'command' && isRoot && this.runInput.continueFrom) {
            throw new Error('Conversation continuation requires an agent action');
        }
        if (action.autoFinish && (
            this.context.kind !== 'card'
            || typeof this.context.cardInternalId !== 'string'
            || this.context.cardInternalId.length === 0
        )) {
            throw new Error(`Action "${action.label}" requires card context for autoFinish`);
        }

        return this.actionWorktreeRunService.execute(this.project, action, this.context, async (project) => {
            this.publish(action, phase, 'running', { type: 'action' });
            const result = action.type === 'agent'
                ? await this.executeAgentAction(action, phase, isRoot, project)
                : await this.executeCommandAction(action, phase, isRoot, project);
            const committedResult = await this.commitTrackedAgentChanges(project, action, result);
            const runProject = {
                ...project,
                branch: committedResult.branch ?? project.branch,
                rootPath: committedResult.repositoryRoot ?? project.rootPath,
            };
            const historyInput = {
                action,
                context: this.context,
                project: runProject,
                projectFolder: this.projectFolder,
                result: committedResult,
            };
            const details = action.type === 'agent'
                ? createAgentDetails(historyInput)
                : createCommandDetails(historyInput);
            const commitReferences = await captureCommitReferences(this.localGitService, historyInput);
            this.collectCommitReferences(commitReferences);
            if (isRoot) {
                this.rootDetails = details;
                if (action.type === 'agent') this.rootConversationId = committedResult.conversationId;
            }
            if (action.type === 'agent' && typeof committedResult.conversationId === 'string') {
                this.conversationIds.push(committedResult.conversationId);
            }

            return committedResult;
        });
    }

    collectCommitReferences(references) {
        for (const reference of references) {
            const key = `${reference.repositoryRoot}\0${reference.commit}`;
            if (this.commitReferenceKeys.has(key)) continue;
            this.commitReferenceKeys.add(key);
            this.commitReferences.push(reference);
        }
    }

    async persistRootActivity(status, failure) {
        const completedAt = new Date().toISOString();
        const commits = this.commitReferences.map((reference) => {
            const persisted = Object.fromEntries(Object.entries(reference).filter(([fieldName]) => fieldName !== 'repositoryRoot'));
            if (reference.actionId === this.rootAction.id) {
                delete persisted.actionId;
                delete persisted.actionName;
            }

            return persisted;
        });
        if (this.rootAction.type === 'agent' && typeof this.rootConversationId !== 'string') {
            return;
        }
        const details = this.rootDetails ?? {
            command: this.rootAction.command,
            output: failure ? errorMessage(failure, 'Action failed') : '',
            type: 'command',
        };
        const record = {
            commits,
            completedAt,
            conversationIds: [...new Set(this.conversationIds)],
            details,
            runId: this.runId,
            origin: this.activityOrigin,
            rootActionId: this.rootAction.id,
            rootActionLabel: this.rootAction.label,
            ...(this.rootConversationId ? { rootConversationId: this.rootConversationId } : {}),
            startedAt: this.startedAt,
            status,
        };
        await this.localGitService.appendAndCommitActionActivity(
            this.project,
            this.projectFolder,
            this.activityOrigin,
            record,
            `Record ${this.rootAction.label} activity`,
        );
    }

    async commitTrackedAgentChanges(project, action, result) {
        if (action.type !== 'agent' || !action.trackFileChanges) return result;
        if (result.exitCode !== 0 || this.controller.signal.aborted) return result;
        const changedPaths = result.changedPaths ?? [];
        if (changedPaths.length === 0) return result;
        const trackedCommit = await this.localGitService.commitTrackedPaths(
            project.rootPath,
            changedPaths,
            action.label,
            this.controller.signal,
        );

        return { ...result, trackedCommit };
    }

    executeCommandAction(action, phase, isRoot, project) {
        const onOutput = ({ command, stderr, stdout }) => {
            if (stdout.length > 0) this.publish(action, phase, 'running', { type: 'update', update: { command, content: stdout, kind: 'output' } });
            if (stderr.length > 0) this.publish(action, phase, 'running', { type: 'update', update: { command, content: stderr, kind: 'error' } });
        };

        return executeCommandAction({
            action,
            activeCardsFolder: this.activeCardsFolder,
            commandRunner: this.commandRunner,
            context: this.context,
            extraPrompt: isRoot ? this.runInput.extraPrompt : '',
            onOutput,
            primaryProject: this.project,
            project,
            projectFolder: this.projectFolder,
            releasesFolder: this.releasesFolder,
            signal: this.controller.signal,
        });
    }

    async executeAgentAction(action, phase, isRoot, project) {
        const onActiveRunChange = (runId) => {
            this.activeAgentRunId = runId;
            if (runId) {
                this.publish(action, phase, 'running', { interactionReady: true, type: 'agentState' });
                if (this.autoFinishPending) {
                    this.autoFinishPending = false;
                    this.agentRunnerService.finish(runId);
                }
            }
            else {
                this.activeAgentQuestion = false;
                this.activeAgentApprovals.clear();
                this.publish(action, phase, 'running', { interactionReady: false, type: 'agentState' });
            }
        };
        const onEvent = (agentEvent) => {
            if (agentEvent.type === 'started') {
                const { continued, conversation } = agentEvent;
                const update = { continued, conversation, kind: 'agentStarted' };
                this.publish(action, phase, 'running', { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'closed') {
                const update = { conversation: agentEvent.conversation, kind: 'agentClosed' };
                this.publish(action, phase, agentEvent.conversation.status, { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'state') {
                this.publish(action, phase, agentEvent.state, { interactionReady: true, type: 'agentState' });
                return;
            }
            if (agentEvent.type === 'question') {
                this.activeAgentQuestion = true;
                const update = {
                    kind: 'agentQuestion',
                    questions: agentEvent.questions,
                    requestId: agentEvent.requestId,
                };
                this.publish(action, phase, 'waitingForInput', { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'userMessage') {
                this.activeAgentQuestion = false;
                const update = { kind: 'agentUserMessage', userMessage: agentEvent.userMessage };
                this.publish(action, phase, 'running', { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'questionAnswered') {
                this.activeAgentQuestion = false;
                const update = { kind: 'agentQuestionAnswer', userMessage: agentEvent.userMessage };
                this.publish(action, phase, agentEvent.state, { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'approval') {
                this.activeAgentApprovals.set(agentEvent.approval.requestId, { ...agentEvent.approval, submitted: false });
                const update = { approval: agentEvent.approval, kind: 'agentApproval' };
                this.publish(action, phase, 'waitingForInput', { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'approvalSubmitted') {
                const approval = this.activeAgentApprovals.get(agentEvent.requestId);
                if (!approval) return;
                approval.submitted = true;
                const update = { kind: 'agentApprovalSubmitted', requestId: agentEvent.requestId };
                this.publish(action, phase, 'waitingForInput', { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'approvalResolved') {
                if (!this.activeAgentApprovals.delete(agentEvent.requestId)) return;
                const update = { kind: 'agentApprovalResolved', requestId: agentEvent.requestId };
                this.publish(action, phase, agentEvent.state, { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'agentEvent') {
                const update = { event: agentEvent.event, kind: 'agentEvent' };
                this.publish(action, phase, 'running', { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'usage') {
                const update = {
                    ...(agentEvent.contextWindowUsage !== undefined
                        ? { contextWindowUsage: agentEvent.contextWindowUsage }
                        : {}),
                    kind: 'agentUsage',
                    usage: agentEvent.usage,
                };
                this.publish(action, phase, 'running', { type: 'update', update });
                return;
            }

            const update = {
                content: agentEvent.content,
                kind: agentEvent.type,
                ...(agentEvent.messageId !== undefined ? { messageId: agentEvent.messageId } : {}),
                ...(agentEvent.previousContent !== undefined ? { previousContent: agentEvent.previousContent } : {}),
                ...(agentEvent.replace !== undefined ? { replace: agentEvent.replace } : {}),
                ...(agentEvent.sequence !== undefined ? { sequence: agentEvent.sequence } : {}),
            };
            this.publish(action, phase, 'running', { type: 'update', update });
        };
        const runInput = isRoot ? this.runInput : { extraPrompt: '' };

        const input = {
            action,
            activeCardsFolder: this.activeCardsFolder,
            activityOrigin: this.activityOrigin,
            context: this.context,
            conversationReservation: isRoot ? this.conversationReservation : null,
            runId: this.runId,
            onActiveRunChange,
            onEvent,
            project,
            projectFolder: this.projectFolder,
            primaryProject: this.project,
            releasesFolder: this.releasesFolder,
            runInput,
            signal: this.controller.signal,
        };
        let result = await this.agentExecutor.execute(input);
        const changedPaths = new Set(result.changedPaths ?? []);
        let stderr = result.stderr ?? '';
        let stdout = result.stdout ?? '';
        while (result.exitCode === 0 && result.queuedMessage) {
            const queuedMessage = result.queuedMessage;
            result = await this.agentExecutor.execute({
                ...input,
                runInput: {
                    ...runInput,
                    continueFrom: result.reference,
                    prompt: queuedMessage,
                },
            });
            for (const changedPath of result.changedPaths ?? []) changedPaths.add(changedPath);
            stderr += result.stderr ?? '';
            stdout += result.stdout ?? '';
        }

        return { ...result, changedPaths: [...changedPaths], stderr, stdout };
    }

    publish(action, phase, status, details) {
        const event = {
            actionId: action.id,
            actionType: action.type,
            autoFinish: action.autoFinish ?? null,
            context: this.context,
            runId: this.runId,
            interactionReady: details.interactionReady ?? false,
            phase,
            rootActionId: this.rootAction.id,
            status,
            streaming: action.type === 'agent' && action.streaming,
            ...details,
            sequence: this.nextEventSequence,
        };
        this.nextEventSequence += 1;
        this.publisher(event);
    }

    throwIfCancelled() {
        if (this.controller.signal.aborted) throw new ActionCancellationError('Action cancelled');
    }
}

module.exports = { ActionRun };

import { actionContextIdentity } from '../../data/action_context'
import type { ActionContext } from '../../data/action_context'
import type { ActionDefinition } from '../../data/action_types'
import type { AgentConversation, AgentConversationEntry, AgentConversationEventEntry } from '../../data/data_types'
import type {
    AgentApproval,
    AgentApprovalDecision,
    AgentApprovalRequestId,
    AgentConversationReservation,
    AgentQuestion,
    ActionRunEvent,
    ActionRunStatus,
    ActionRunTerminalStatus,
    ActionRunUpdate,
    ActionRunInput,
    ActionRunLogEntry,
    ActionRunResult,
} from '../../data/action_run_types'
import { getElectronActionBridge } from '../../data/electron_action_bridge'
import type { ElectronActionBridge } from '../../data/electron_action_bridge'
import { actionService } from './action_service'
import { actionPromptDraftService } from './action_prompt_draft_service'
import { register } from '../service_injector'
import { projectAccessService } from '../project/project_access_service'

const TERMINAL_STATUSES = new Set<ActionRunTerminalStatus>(['cancelled', 'completed', 'failed', 'okButNotAfter'])
const ACTIVE_STATUSES = new Set<ActionRunStatus>(['queued', 'running', 'waitingForInput'])
const EMPTY_ACTIVE_RUNS: ActiveActionRun[] = []

export interface ActionRun {
    activeActionAutoFinish: ActionDefinition['autoFinish']
    activeActionId: string | null
    activeActionStreaming: boolean
    activeActionType: ActionDefinition['type'] | null
    conversation: AgentConversation | null
    context: ActionContext
    runId: string
    logs: ActionRunLogEntry[]
    approvals: LiveAgentApproval[]
    interactionReady: boolean
    question: LiveAgentQuestion | null
    reference: string | null
    rootActionId: string
    status: ActionRunStatus
}

export interface LiveAgentApproval extends AgentApproval {
    submitted: boolean
}

export interface LiveAgentQuestion {
    questions: AgentQuestion[]
    requestId: number | string | null
}

export interface ActiveActionRun {
    rootActionId: string
    runId: string
    status: ActionRunStatus
}

type EventListener = (event: ActionRunEvent) => void
type StoreListener = () => void

function actionName(actionId: string) {
    return actionService.getActions().find((action) => action.id === actionId)?.label ?? actionId
}

function actionType(actionId: string) {
    return actionService.getActions().find((action) => action.id === actionId)?.type ?? null
}

function actionStreaming(actionId: string) {
    return actionService.getActions().find((action) => action.id === actionId)?.streaming ?? false
}

function createLog(event: ActionRunEvent): ActionRunLogEntry {
    return {
        actionId: event.actionId,
        actionName: actionName(event.actionId),
        command: event.type === 'action' ? event.command ?? null : null,
        message: event.type === 'action' ? event.message ?? `${actionName(event.actionId)} ${event.status}` : `${actionName(event.actionId)} running`,
        phase: event.phase,
        ...(event.type === 'action' && event.permissionMode ? { permissionMode: event.permissionMode } : {}),
        status: event.status,
        stderr: '',
        stdout: '',
        ...(event.type === 'action' && event.thinkingLevel ? { thinkingLevel: event.thinkingLevel } : {}),
    }
}

function runningLogIndex(logs: ActionRunLogEntry[], event: ActionRunEvent) {
    return logs.findLastIndex((log) => (
        log.actionId === event.actionId
        && log.phase === event.phase
        && (log.status === 'queued' || log.status === 'running')
    ))
}

type AgentOutputUpdate = Pick<
    Extract<ActionRunUpdate, { kind: 'error' | 'output' }>,
    'content' | 'previousContent' | 'replace'
>

function updatedStdout(currentStdout: string, update: AgentOutputUpdate) {
    if (!update.replace) return `${currentStdout}${update.content}`
    if (update.previousContent === undefined) throw new Error('Missing previous assistant output')
    if (!currentStdout.endsWith(update.previousContent)) throw new Error('Assistant output replacement is out of order')

    return `${currentStdout.slice(0, currentStdout.length - update.previousContent.length)}${update.content}`
}

function updateActionLogs(logs: ActionRunLogEntry[], event: Extract<ActionRunEvent, { type: 'action' }>) {
    const currentIndex = runningLogIndex(logs, event)
    if (currentIndex < 0) return [...logs, createLog(event)]
    const current = logs[currentIndex]
    const next = [...logs]
    next[currentIndex] = {
        ...current,
        command: event.command ?? current.command,
        message: event.message ?? `${actionName(event.actionId)} ${event.status}`,
        ...(event.permissionMode ? { permissionMode: event.permissionMode } : {}),
        status: event.status,
        ...(event.thinkingLevel ? { thinkingLevel: event.thinkingLevel } : {}),
    }

    return next
}

function updateOutputLogs(
    logs: ActionRunLogEntry[],
    event: Extract<ActionRunEvent, { type: 'update' }>,
    update: Extract<ActionRunUpdate, { kind: 'error' | 'output' }>,
) {
    const currentIndex = logs.findLastIndex((log) => (
        log.actionId === event.actionId && log.phase === event.phase && log.status === 'running'
    ))
    const current = currentIndex >= 0 ? logs[currentIndex] : createLog(event)
    const updated = {
        ...current,
        command: update.command ?? current.command,
        stderr: update.kind === 'error' ? `${current.stderr}${update.content}` : current.stderr,
        stdout: update.kind === 'output' ? updatedStdout(current.stdout, update) : current.stdout,
    }
    if (currentIndex < 0) return [...logs, updated]
    const next = [...logs]
    next[currentIndex] = updated

    return next
}

function eventIdentity(event: AgentConversationEventEntry) {
    return event.providerItemId ?? event.id
}

function upsertAgentEvent(entries: AgentConversationEntry[], event: AgentConversationEventEntry) {
    const identity = eventIdentity(event)
    const currentIndex = entries.findIndex((entry) => entry.kind === 'event' && eventIdentity(entry) === identity)
    if (currentIndex < 0) return [...entries, event]

    const current = entries[currentIndex]
    const next = [...entries]
    next[currentIndex] = {
        ...event,
        ...(event.sequence === undefined && current.sequence !== undefined ? { sequence: current.sequence } : {}),
    }

    return next
}

function nextConversationSequence(conversation: AgentConversation) {
    const sequences = conversation.entries.map(({ sequence }) => sequence)
        .filter((sequence): sequence is number => sequence !== undefined)

    return sequences.length > 0 ? Math.max(...sequences) + 1 : undefined
}

function appendAssistantMessage(
    conversation: AgentConversation,
    update: { content: string, messageId?: string, replace?: boolean, sequence?: number },
) {
    const sequence = update.sequence ?? nextConversationSequence(conversation)
    const latestUserIndex = conversation.entries.findLastIndex((entry) => entry.kind === 'message' && entry.role === 'user')
    const currentAssistantMessage = conversation.entries.slice(latestUserIndex + 1)
        .findLast((entry) => entry.kind === 'message' && entry.role === 'assistant')
    const messageId = update.messageId
        ?? currentAssistantMessage?.id
        ?? `${conversation.id}-assistant-${sequence ?? conversation.entries.length + 1}`
    const currentIndex = conversation.entries.findIndex((entry) => entry.kind === 'message' && entry.id === messageId)
    const entries: AgentConversationEntry[] = currentIndex < 0
        ? [...conversation.entries, {
            content: update.content,
            id: messageId,
            kind: 'message',
            role: 'assistant' as const,
            ...(sequence !== undefined ? { sequence } : {}),
            timestamp: conversation.startedAt,
        }]
        : conversation.entries.map((entry, index) => index === currentIndex
            ? { ...entry, content: update.replace ? update.content : `${entry.content}${update.content}` }
            : entry)

    return { ...conversation, entries }
}

function conversationStatus(status: ActionRunStatus): AgentConversation['status'] {
    if (status === 'queued') return 'running'
    if (status === 'okButNotAfter') return 'completed'

    return status
}

function contextKey(context: ActionContext) {
    return actionContextIdentity(context)
}

export async function cancelActionRun(runId: string) {
    const bridge = getElectronActionBridge()
    if (!bridge) throw new Error('Action cancellation requires Electron')

    await bridge.cancelActionRun(runId)
}

export async function sendActionMessage(runId: string, content: string) {
    const bridge = getElectronActionBridge()
    if (!bridge?.sendActionMessage) throw new Error('Streaming agent messaging requires Electron')

    await bridge.sendActionMessage(runId, content)
}

export async function answerActionQuestion(
    runId: string,
    requestId: number | string | null,
    answers: Record<string, string[]>,
) {
    const bridge = getElectronActionBridge()
    if (!bridge?.answerActionQuestion) throw new Error('Streaming agent questions require Electron')

    await bridge.answerActionQuestion(runId, requestId, answers)
}

export async function answerActionApproval(
    runId: string,
    requestId: AgentApprovalRequestId,
    decision: AgentApprovalDecision,
) {
    const bridge = getElectronActionBridge()
    if (!bridge?.answerActionApproval) throw new Error('Streaming agent approvals require Electron')

    await bridge.answerActionApproval(runId, requestId, decision)
}

export async function finishActionRun(runId: string) {
    const bridge = getElectronActionBridge()
    if (!bridge?.finishActionRun) throw new Error('Finishing a streaming agent requires Electron')

    await bridge.finishActionRun(runId)
}

export async function notifyActionCardStateChange(cardInternalId: string | null, state: string) {
    if (!cardInternalId) return
    const bridge = getElectronActionBridge()
    if (!bridge?.notifyActionCardStateChange) throw new Error('Automatic agent finish requires Electron')

    await bridge.notifyActionCardStateChange(cardInternalId, state)
}

/** Stable state owner for one action run. */
export class ActionRunStore {
    private readonly listeners = new Set<StoreListener>()
    private readonly onReleased: (store: ActionRunStore) => void
    private snapshot: ActionRun

    constructor(snapshot: ActionRun, onReleased: (store: ActionRunStore) => void) {
        this.onReleased = onReleased
        this.snapshot = snapshot
    }

    readonly getSnapshot = () => this.snapshot

    readonly subscribe = (listener: StoreListener) => {
        this.listeners.add(listener)

        return () => {
            this.listeners.delete(listener)
            this.onReleased(this)
        }
    }

    hasConsumers() {
        return this.listeners.size > 0
    }

    update(snapshot: ActionRun) {
        this.snapshot = snapshot
        for (const listener of this.listeners) listener()
    }
}

function actionContextKey(actionId: string, context: ActionContext) {
    return `${actionId}\u0000${contextKey(context)}`
}

function activeRun(run: ActionRun): ActiveActionRun {
    return { rootActionId: run.rootActionId, runId: run.runId, status: run.status }
}

function sameActiveRuns(first: ActiveActionRun[], second: ActiveActionRun[]) {
    return first.length === second.length && first.every(({ runId, status }, index) => (
        second[index]?.runId === runId && second[index]?.status === status
    ))
}

function publishKey(map: Map<string, Set<StoreListener>>, key: string) {
    const listeners = map.get(key) ?? []
    for (const listener of listeners) listener()
}

function publishListeners(map: Map<string, Set<StoreListener>>) {
    for (const listeners of map.values()) {
        for (const listener of listeners) listener()
    }
}

/** Owns one renderer-wide bridge subscription and routes events to scoped run stores. */
export class ActionRunRegistry extends EventTarget {
    private readonly actionContextListeners = new Map<string, Set<StoreListener>>()
    private readonly actionContextStores = new Map<string, ActionRunStore>()
    private readonly activeRunEventListeners = new Set<EventListener>()
    private readonly contextActiveListeners = new Map<string, Set<StoreListener>>()
    private readonly contextActiveSnapshots = new Map<string, ActiveActionRun[]>()
    private readonly contextEventListeners = new Map<string, Set<EventListener>>()
    private eventSequences = new Map<string, number>()
    private readonly globalActiveListeners = new Set<StoreListener>()
    private globalActiveSnapshot: ActiveActionRun[] = EMPTY_ACTIVE_RUNS
    private recoveryEvents: ActionRunEvent[] | null = null
    private runs = new Map<string, ActionRunStore>()
    private subscribedBridge: ElectronActionBridge | null = null
    private startsInProgress = 0
    private readonly terminalResults = new Map<string, ActionRunResult>()
    private unsubscribeBridge: (() => void) | null = null
    private readonly waiters = new Map<string, Set<(result: ActionRunResult) => void>>()

    constructor() {
        super()
        register('actionRunRegistry', this)
    }

    start() {
        const bridge = getElectronActionBridge()
        if (!bridge) return
        if (this.unsubscribeBridge && bridge === this.subscribedBridge) return

        this.unsubscribeBridge?.()
        this.subscribedBridge = bridge
        this.recoveryEvents = bridge.loadActiveActionRunEvents ? [] : null
        this.unsubscribeBridge = bridge.onActionRun((event) => this.handleIncomingEvent(event))
        if (bridge.loadActiveActionRunEvents) void this.recoverActiveRuns(bridge)
    }

    stop() {
        this.unsubscribeBridge?.()
        this.subscribedBridge = null
        this.unsubscribeBridge = null
        this.eventSequences = new Map()
        this.recoveryEvents = null
        this.runs = new Map()
        this.actionContextStores.clear()
        this.contextActiveSnapshots.clear()
        this.publishGlobalActive([])
        publishListeners(this.actionContextListeners)
        publishListeners(this.contextActiveListeners)
    }

    getRunStore(runId: string) {
        return this.runs.get(runId) ?? null
    }

    getActionRunStore(actionId: string, context: ActionContext) {
        return this.getActionRunStoreByKey(actionId, contextKey(context))
    }

    getActionRunStoreByKey(actionId: string, contextIdentity: string) {
        return this.actionContextStores.get(`${actionId}\u0000${contextIdentity}`) ?? null
    }

    getContextActiveSnapshot(context: ActionContext) {
        return this.getContextActiveSnapshotByKey(contextKey(context))
    }

    getContextActiveSnapshotByKey(contextIdentity: string) {
        return this.contextActiveSnapshots.get(contextIdentity) ?? EMPTY_ACTIVE_RUNS
    }

    getGlobalActiveSnapshot = () => this.globalActiveSnapshot

    subscribeActionRun(actionId: string, context: ActionContext, listener: StoreListener) {
        return this.subscribeActionRunByKey(actionId, contextKey(context), listener)
    }

    subscribeActionRunByKey(actionId: string, contextIdentity: string, listener: StoreListener) {
        const key = `${actionId}\u0000${contextIdentity}`
        const unsubscribe = this.subscribeMap(this.actionContextListeners, key, listener)

        return () => {
            unsubscribe()
            const store = this.actionContextStores.get(key)
            if (store) this.releaseTerminalRun(store.getSnapshot().runId)
        }
    }

    subscribeContextActive(context: ActionContext, listener: StoreListener) {
        return this.subscribeContextActiveByKey(contextKey(context), listener)
    }

    subscribeContextActiveByKey(contextIdentity: string, listener: StoreListener) {
        return this.subscribeMap(this.contextActiveListeners, contextIdentity, listener)
    }

    subscribeContextEvents(context: ActionContext, listener: EventListener) {
        return this.subscribeMap(this.contextEventListeners, contextKey(context), listener)
    }

    subscribeActiveRunEvents(listener: EventListener) {
        this.activeRunEventListeners.add(listener)
        this.start()

        return () => this.activeRunEventListeners.delete(listener)
    }

    readonly subscribeGlobalActive = (listener: StoreListener) => {
        this.globalActiveListeners.add(listener)
        this.start()

        return () => this.globalActiveListeners.delete(listener)
    }

    async startRun(
        action: ActionDefinition,
        context: ActionContext,
        runInput: ActionRunInput = {},
        onStarted?: (runId: string) => void,
        interactive = true,
        conversationReservation?: AgentConversationReservation,
    ) {
        projectAccessService.requireWritable()
        const bridge = getElectronActionBridge()
        if (!bridge) throw new Error('Action run requires Electron')
        this.start()
        const start = interactive ? bridge.startAction.bind(bridge) : bridge.startUnattendedAction?.bind(bridge)
        if (!start) throw new Error('Unattended action run requires Electron')
        this.startsInProgress += 1
        let runId: string
        try {
            runId = await start({ actionId: action.id, ...(conversationReservation ? { conversationReservation } : {}), context, runInput })
        } finally {
            this.startsInProgress -= 1
        }
        onStarted?.(runId)

        return this.waitForRun(runId)
    }

    async restartRun(
        previousRunId: string,
        action: ActionDefinition,
        context: ActionContext,
        runInput: ActionRunInput,
        onStarted?: (runId: string) => void,
    ) {
        projectAccessService.requireWritable()
        const bridge = getElectronActionBridge()
        if (!bridge?.restartActionRun) throw new Error('Restarting an action run requires Electron')
        this.start()
        this.startsInProgress += 1
        let runId: string
        try {
            runId = await bridge.restartActionRun(previousRunId, { actionId: action.id, context, runInput })
        } finally {
            this.startsInProgress -= 1
            this.terminalResults.delete(previousRunId)
        }
        onStarted?.(runId)

        return this.waitForRun(runId)
    }

    private waitForRun(runId: string): Promise<ActionRunResult> {
        const terminalResult = this.terminalResults.get(runId)
        if (terminalResult) {
            this.terminalResults.delete(runId)

            return Promise.resolve(terminalResult)
        }
        const current = this.runs.get(runId)?.getSnapshot()
        if (current && TERMINAL_STATUSES.has(current.status as ActionRunTerminalStatus)) {
            const result = { logs: current.logs, status: current.status as ActionRunTerminalStatus }
            this.releaseTerminalRun(runId)

            return Promise.resolve(result)
        }

        return new Promise((resolve) => {
            const waiters = this.waiters.get(runId) ?? new Set()
            waiters.add(resolve)
            this.waiters.set(runId, waiters)
        })
    }

    private async recoverActiveRuns(bridge: ElectronActionBridge) {
        try {
            const events = await bridge.loadActiveActionRunEvents?.() ?? []
            if (this.subscribedBridge !== bridge || !this.recoveryEvents) return
            const recoveryEvents = this.recoveryEvents
            this.recoveryEvents = null
            for (const event of events) this.handleEvent(event)
            for (const event of recoveryEvents) this.handleEvent(event)
        } catch (error) {
            if (this.subscribedBridge !== bridge) return
            const recoveryEvents = this.recoveryEvents ?? []
            this.recoveryEvents = null
            for (const event of recoveryEvents) this.handleEvent(event)
            this.dispatchEvent(new CustomEvent('recoveryFailed', { detail: error }))
        }
    }

    private handleIncomingEvent(event: ActionRunEvent) {
        if (this.recoveryEvents) {
            this.recoveryEvents.push(event)
            return
        }

        this.handleEvent(event)
    }

    private handleEvent(event: ActionRunEvent) {
        if (event.sequence !== undefined) {
            const currentSequence = this.eventSequences.get(event.runId) ?? 0
            if (event.sequence <= currentSequence) return
            this.eventSequences.set(event.runId, event.sequence)
        }
        const store = this.runs.get(event.runId)
        const current = store?.getSnapshot() ?? {
            activeActionAutoFinish: null,
            activeActionId: null,
            activeActionStreaming: false,
            activeActionType: null,
            conversation: null,
            approvals: [],
            context: event.context,
            runId: event.runId,
            logs: [],
            interactionReady: false,
            question: null,
            reference: null,
            rootActionId: event.rootActionId,
            status: 'running' as const,
        }
        let next = { ...current, context: event.context, rootActionId: event.rootActionId }
        if (event.type === 'run') next = { ...next, status: event.status }
        if (event.type === 'run' && TERMINAL_STATUSES.has(event.status as ActionRunTerminalStatus)) {
            next = { ...next, approvals: [], question: null }
            actionPromptDraftService.clearRunDrafts(event.runId)
        }
        if (event.type === 'agentState') next = { ...next, status: event.status }
        if (event.type === 'action') {
            const active = event.status === 'queued' || event.status === 'running'
            const activeType = event.actionType ?? actionType(event.actionId)
            next = {
                ...next,
                activeActionAutoFinish: active ? event.autoFinish ?? null : null,
                activeActionId: active ? event.actionId : null,
                activeActionStreaming: active && (event.streaming ?? actionStreaming(event.actionId)),
                activeActionType: active ? activeType : null,
                interactionReady: active && !!event.interactionReady,
                logs: updateActionLogs(next.logs, event),
                reference: event.reference ?? next.reference,
            }
            if (active) next.status = event.status
            if (!active) actionPromptDraftService.clearRunDraft(event.runId, event.actionId)
        }
        if (event.type === 'agentState') {
            next = {
                ...next,
                activeActionAutoFinish: event.autoFinish ?? null,
                activeActionId: event.actionId,
                activeActionStreaming: event.streaming ?? actionStreaming(event.actionId),
                activeActionType: event.actionType ?? actionType(event.actionId),
                conversation: next.conversation
                    ? { ...next.conversation, completedAt: null, status: event.status }
                    : null,
                interactionReady: event.interactionReady ?? true,
            }
        }
        if (event.type === 'update' && event.update.kind === 'agentStarted') {
            const { continued } = event.update
            next = { ...next, conversation: event.update.conversation }
            if (continued) actionPromptDraftService.clearRunDraft(event.runId, event.actionId)
        }
        if (event.type === 'update' && event.update.kind === 'agentClosed') {
            next = { ...next, conversation: event.update.conversation }
        }
        if (event.type === 'update' && event.update.kind === 'agentEvent' && next.conversation) {
            next = {
                ...next,
                conversation: {
                    ...next.conversation,
                    entries: upsertAgentEvent(next.conversation.entries, event.update.event),
                },
            }
        }
        if (event.type === 'update' && event.update.kind === 'agentUsage' && next.conversation) {
            const conversation = { ...next.conversation, usage: event.update.usage }
            if (event.update.contextWindowUsage !== undefined) {
                if (event.update.contextWindowUsage) conversation.contextWindowUsage = event.update.contextWindowUsage
                else delete conversation.contextWindowUsage
            }
            next = { ...next, conversation }
        }
        if (event.type === 'update' && event.update.kind === 'agentQuestion') {
            next = {
                ...next,
                question: { questions: event.update.questions, requestId: event.update.requestId },
                status: 'waitingForInput',
            }
        }
        if (event.type === 'update' && event.update.kind === 'agentApproval') {
            const requestId = event.update.approval.requestId
            const approvals = next.approvals.filter((approval) => approval.requestId !== requestId)
            next = {
                ...next,
                approvals: [...approvals, { ...event.update.approval, submitted: false }],
                status: 'waitingForInput',
            }
        }
        if (event.type === 'update' && event.update.kind === 'agentApprovalSubmitted') {
            const { requestId } = event.update
            next = {
                ...next,
                approvals: next.approvals.map((approval) => approval.requestId === requestId
                    ? { ...approval, submitted: true }
                    : approval),
            }
        }
        if (event.type === 'update' && event.update.kind === 'agentApprovalResolved') {
            const { requestId } = event.update
            const approvals = next.approvals.filter((approval) => approval.requestId !== requestId)
            next = {
                ...next,
                approvals,
                status: next.question || approvals.length > 0 ? 'waitingForInput' : event.status,
            }
        }
        if (
            event.type === 'update'
            && (event.update.kind === 'agentUserMessage' || event.update.kind === 'agentQuestionAnswer')
            && next.conversation
        ) {
            next = {
                ...next,
                conversation: {
                    ...next.conversation,
                    entries: [...next.conversation.entries, event.update.userMessage],
                },
                question: null,
                status: next.approvals.length > 0 ? 'waitingForInput' : event.status,
            }
            if (event.update.kind === 'agentUserMessage') {
                actionPromptDraftService.clearRunDraft(event.runId, event.actionId)
            }
        }
        if (event.type === 'update' && (event.update.kind === 'output' || event.update.kind === 'error')) {
            const conversation = event.update.kind === 'output' && next.conversation
                ? appendAssistantMessage(next.conversation, event.update)
                : next.conversation
            next = { ...next, conversation, logs: updateOutputLogs(next.logs, event, event.update) }
        }
        if (
            event.type === 'update'
            && event.update.kind !== 'agentClosed'
            && event.update.kind !== 'agentUsage'
            && next.conversation
        ) {
            next = {
                ...next,
                conversation: { ...next.conversation, status: conversationStatus(event.status) },
            }
        }
        const nextStore = store ?? new ActionRunStore(next, (releasedStore) => this.handleStoreReleased(releasedStore))
        if (!store) {
            this.runs.set(event.runId, nextStore)
            const bindingKey = actionContextKey(event.rootActionId, event.context)
            this.actionContextStores.set(bindingKey, nextStore)
            publishKey(this.actionContextListeners, bindingKey)
        } else nextStore.update(next)

        this.publishActiveIndexes(contextKey(current.context), contextKey(next.context))
        this.publishScopedEvents(event)
        if (event.type === 'run' && TERMINAL_STATUSES.has(event.status as ActionRunTerminalStatus)) {
            this.resolveWaiters(next)
            this.releaseTerminalRun(event.runId)
        }
    }

    private publishActiveIndexes(previousContextKey: string, nextContextKey: string) {
        const affectedContextKeys = new Set([previousContextKey, nextContextKey])
        for (const affectedContextKey of affectedContextKeys) {
            const nextSnapshot = [...this.runs.values()]
                .map((store) => store.getSnapshot())
                .filter((run) => contextKey(run.context) === affectedContextKey && ACTIVE_STATUSES.has(run.status))
                .map(activeRun)
            const currentSnapshot = this.contextActiveSnapshots.get(affectedContextKey) ?? []
            if (sameActiveRuns(currentSnapshot, nextSnapshot)) continue

            if (nextSnapshot.length > 0) this.contextActiveSnapshots.set(affectedContextKey, nextSnapshot)
            else this.contextActiveSnapshots.delete(affectedContextKey)
            publishKey(this.contextActiveListeners, affectedContextKey)
        }
        const nextGlobalSnapshot = [...this.runs.values()]
            .map((store) => store.getSnapshot())
            .filter((run) => ACTIVE_STATUSES.has(run.status))
            .map(activeRun)
        if (!sameActiveRuns(this.globalActiveSnapshot, nextGlobalSnapshot)) this.publishGlobalActive(nextGlobalSnapshot)
    }

    private publishScopedEvents(event: ActionRunEvent) {
        const listeners = this.contextEventListeners.get(contextKey(event.context)) ?? []
        for (const listener of listeners) listener(event)
        for (const listener of this.activeRunEventListeners) listener(event)
    }

    private resolveWaiters(run: ActionRun) {
        const waiters = this.waiters.get(run.runId)
        this.waiters.delete(run.runId)
        const result = { logs: run.logs, status: run.status as ActionRunTerminalStatus }
        if (!waiters && this.startsInProgress > 0) this.terminalResults.set(run.runId, result)
        for (const resolve of waiters ?? []) resolve(result)
    }

    private handleStoreReleased(store: ActionRunStore) {
        const { runId, status } = store.getSnapshot()
        if (TERMINAL_STATUSES.has(status as ActionRunTerminalStatus)) this.releaseTerminalRun(runId)
    }

    private releaseTerminalRun(runId: string) {
        const store = this.runs.get(runId)
        if (!store || store.hasConsumers() || this.waiters.has(runId)) return

        const run = store.getSnapshot()
        const bindingKey = actionContextKey(run.rootActionId, run.context)
        if ((this.actionContextListeners.get(bindingKey)?.size ?? 0) > 0) return

        this.runs.delete(runId)
        this.eventSequences.delete(runId)
        if (this.actionContextStores.get(bindingKey) === store) {
            this.actionContextStores.delete(bindingKey)
            publishKey(this.actionContextListeners, bindingKey)
        }
    }

    private subscribeMap<T>(map: Map<string, Set<T>>, key: string, listener: T) {
        const listeners = map.get(key) ?? new Set<T>()
        listeners.add(listener)
        map.set(key, listeners)
        this.start()

        return () => {
            listeners.delete(listener)
            if (listeners.size === 0) map.delete(key)
        }
    }

    private publishGlobalActive(snapshot: ActiveActionRun[]) {
        this.globalActiveSnapshot = snapshot
        for (const listener of this.globalActiveListeners) listener()
    }
}

export const actionRunRegistry = new ActionRunRegistry()

const { normalizeAgentTokenUsage } = require('../../../../shared/agent_usage_math.mjs');
const { ClaudeStreamingAdapter } = require('./agent_claude_streaming_adapter');
const { codexChangedPaths } = require('./agent_codex_events');
const { diagnosticEvent, normalizeCodexEvent, systemEvent } = require('./agent_codex_event');
const { isMissingSession } = require('./agent_provider_protocol');

const CODEX_CLIENT_NAME = 'md2';
const CODEX_CLIENT_VERSION = '1';
const CODEX_MISSING_THREAD_ERROR_CODE = -32600;
const CODEX_APPROVAL_METHODS = new Map([
    ['item/commandExecution/requestApproval', 'commandExecution'],
    ['item/fileChange/requestApproval', 'fileChange'],
]);
const CODEX_COMMAND_APPROVAL_DECISIONS = ['accept', 'acceptForSession', 'decline', 'cancel'];
const CODEX_FILE_APPROVAL_DECISIONS = ['accept', 'acceptForSession', 'decline', 'cancel'];
const CODEX_NON_EVENT_ITEM_TYPES = new Set(['agentMessage', 'hookPrompt', 'userMessage']);

function requireMessage(content) {
    if (typeof content !== 'string' || content.trim().length === 0) throw new Error('Streaming agent message is required');

    return content;
}

function codexInput(content) {
    return [{ text: requireMessage(content), type: 'text' }];
}

// The app-server already reports cache-free input tokens, unlike `codex exec`, so no subtraction here.
function codexUsage(params) {
    const usage = params.tokenUsage?.last;
    if (!usage) return null;

    return normalizeAgentTokenUsage({
        cachedInputTokens: usage.cachedInputTokens,
        inputTokens: usage.inputTokens,
        outputTokens: usage.outputTokens,
        reasoningTokens: usage.reasoningOutputTokens,
    });
}

function codexContextWindowUsage(params) {
    const usedTokens = params.tokenUsage?.last?.totalTokens;
    const capacityTokens = params.tokenUsage?.modelContextWindow;
    if (!Number.isSafeInteger(usedTokens) || usedTokens < 0) return null;
    if (!Number.isSafeInteger(capacityTokens) || capacityTokens <= 0) return null;

    return { capacityTokens, usedTokens };
}

function eventTextParts(event, field, index) {
    const parts = [...event[field]];
    while (parts.length <= index) parts.push('');

    return parts;
}

function isCodexMissingThreadError(error, providerConversationId) {
    if (!providerConversationId || error?.code !== CODEX_MISSING_THREAD_ERROR_CODE) return false;

    return error.message === `no rollout found for thread id ${providerConversationId}`;
}

function requireCodexApprovalId(value, field) {
    if (typeof value !== 'string' || value.length === 0) throw new Error(`Missing Codex approval ${field}`);

    return value;
}

function sameDecision(left, right) {
    return JSON.stringify(left) === JSON.stringify(right);
}

function availableApprovalDecisions(approval) {
    if (approval.kind === 'fileChange') return CODEX_FILE_APPROVAL_DECISIONS;
    if (Array.isArray(approval.availableDecisions)) return approval.availableDecisions;

    return CODEX_COMMAND_APPROVAL_DECISIONS;
}

class CodexStreamingAdapter {
    constructor(writeLine, onEvent, rootPath, providerConversationId, onRuntimeEvent) {
        this.writeLine = writeLine;
        this.onEvent = onEvent;
        this.onRuntimeEvent = onRuntimeEvent;
        this.providerConversationId = providerConversationId;
        this.rootPath = rootPath;
        this.activeTurnId = null;
        this.activeItems = new Map();
        this.assistantItemOrder = [];
        this.assistantStreams = new Map();
        this.completedItemIds = new Set();
        this.diagnosticSequence = 1;
        this.initialPrompt = null;
        this.nextRequestId = 1;
        this.pendingRequests = new Map();
        this.pendingApprovals = new Map();
        this.threadId = null;
        this.turnContextWindowUsage = undefined;
        this.turnUsage = null;
    }

    async start(prompt) {
        this.initialPrompt = requireMessage(prompt);
        await this.sendRequest('initialize', {
            capabilities: { experimentalApi: true },
            clientInfo: { name: CODEX_CLIENT_NAME, version: CODEX_CLIENT_VERSION },
        }, 'initialize');
    }

    async sendMessage(content) {
        const input = codexInput(content);
        if (!this.threadId) throw new Error('Codex streaming thread is not ready');
        if (this.activeTurnId) {
            await this.sendRequest('turn/steer', {
                expectedTurnId: this.activeTurnId,
                input,
                threadId: this.threadId,
            });
            return;
        }
        await this.sendRequest('turn/start', { input, threadId: this.threadId });
    }

    async answerQuestion(requestId, answers) {
        if (requestId === null || requestId === undefined) throw new Error('Missing Codex question request id');
        const normalizedAnswers = Object.fromEntries(Object.entries(answers).map(([questionId, answer]) => [
            questionId,
            { answers: Array.isArray(answer) ? answer : [answer] },
        ]));
        await this.writeLine({ id: requestId, result: { answers: normalizedAnswers } });
    }

    async answerApproval(requestId, decision) {
        const pendingApproval = this.pendingApprovals.get(requestId);
        if (!pendingApproval) throw new Error(`Unknown or stale Codex approval request id: ${requestId}`);
        if (pendingApproval.submitted) throw new Error(`Codex approval request was already submitted: ${requestId}`);
        const availableDecisions = availableApprovalDecisions(pendingApproval.approval);
        if (!availableDecisions.some((availableDecision) => sameDecision(availableDecision, decision))) {
            throw new Error(`Unsupported Codex approval decision for request ${requestId}`);
        }
        pendingApproval.submitted = true;
        try {
            await this.writeLine({ id: requestId, result: { decision } });
        } catch (error) {
            pendingApproval.submitted = false;
            throw error;
        }
        await this.onEvent({ requestId, type: 'approvalSubmitted' });
    }

    async sendRequest(method, params, purpose = null) {
        const id = this.nextRequestId;
        this.nextRequestId += 1;
        if (purpose) this.pendingRequests.set(id, purpose);
        try {
            await this.writeLine({ id, method, params });
        } catch (error) {
            this.pendingRequests.delete(id);
            throw error;
        }
    }

    async handleMessage(message) {
        if (Object.hasOwn(message, 'id') && !message.method) {
            await this.handleResponse(message);
            return;
        }
        if (message.method === 'item/tool/requestUserInput') {
            await this.onEvent({ questions: message.params.questions, requestId: message.id, type: 'question' });
            return;
        }
        if (CODEX_APPROVAL_METHODS.has(message.method)) {
            await this.handleApprovalRequest(message);
            return;
        }
        await this.handleNotification(message.method, message.params ?? {});
    }

    async handleApprovalRequest(message) {
        if (message.id === null || message.id === undefined) throw new Error('Missing Codex approval request id');
        if (this.pendingApprovals.has(message.id)) throw new Error(`Duplicate Codex approval request id: ${message.id}`);
        const kind = CODEX_APPROVAL_METHODS.get(message.method);
        const params = message.params;
        if (!params || typeof params !== 'object' || Array.isArray(params)) throw new Error('Missing Codex approval params');
        const threadId = requireCodexApprovalId(params.threadId, 'thread id');
        const turnId = requireCodexApprovalId(params.turnId, 'turn id');
        const itemId = requireCodexApprovalId(params.itemId, 'item id');
        if (threadId !== this.threadId) throw new Error(`Mismatched Codex approval thread id: ${threadId}`);
        if (turnId !== this.activeTurnId) throw new Error(`Mismatched Codex approval turn id: ${turnId}`);
        const trackedItem = this.activeItems.get(itemId);
        if (!trackedItem || trackedItem.itemType !== kind || this.completedItemIds.has(itemId)) {
            throw new Error(`Mismatched Codex approval item id: ${itemId}`);
        }
        const filePaths = kind === 'fileChange'
            ? trackedItem.item.changes
                ?.filter(({ path }) => typeof path === 'string' && path.length > 0)
                .map(({ path }) => path) ?? []
            : [];
        const approval = { ...params, filePaths, kind, provider: 'codex', requestId: message.id };
        this.pendingApprovals.set(message.id, { approval, submitted: false });
        await this.onEvent({ approval, type: 'approval' });
    }

    async handleResponse(message) {
        const purpose = this.pendingRequests.get(message.id);
        if (!purpose) {
            if (message.error) await this.onEvent({ content: message.error.message ?? 'Codex request failed', type: 'fatal' });
            return;
        }
        this.pendingRequests.delete(message.id);
        if (message.error) {
            const content = message.error.message ?? `Codex ${purpose} failed`;
            if (purpose === 'rateLimitsRead') {
                await this.onRuntimeEvent({ kind: 'unavailable', observedAt: Date.now() });
                return;
            }
            if (purpose === 'threadResume') {
                const missingSession = isCodexMissingThreadError(message.error, this.providerConversationId)
                    || isMissingSession('codex', { error: message.error, type: 'error' }, false);
                await this.onEvent({ content, missingSession, type: 'sessionFailed' });
                return;
            }
            await this.onEvent({ content, type: 'fatal' });
            return;
        }
        if (purpose === 'initialize') {
            await this.writeLine({ method: 'initialized', params: {} });
            await this.sendRequest('account/rateLimits/read', undefined, 'rateLimitsRead');
            if (this.providerConversationId) {
                await this.sendRequest('thread/resume', {
                    cwd: this.rootPath,
                    threadId: this.providerConversationId,
                }, 'threadResume');
                return;
            }
            await this.sendRequest('thread/start', { cwd: this.rootPath }, 'threadStart');
            return;
        }
        if (purpose === 'threadStart' || purpose === 'threadResume') {
            this.threadId = message.result?.thread?.id ?? message.result?.threadId ?? this.providerConversationId;
            if (!this.threadId) throw new Error('Codex app-server did not return a thread id');
            await this.onEvent({ conversationId: this.threadId, type: 'sessionStarted' });
            await this.sendMessage(this.initialPrompt);
            return;
        }
        if (purpose === 'rateLimitsRead') {
            const hasSingleBucket = !!message.result?.rateLimits && typeof message.result.rateLimits === 'object';
            const hasBuckets = !!message.result?.rateLimitsByLimitId
                && typeof message.result.rateLimitsByLimitId === 'object'
                && Object.keys(message.result.rateLimitsByLimitId).length > 0;
            await this.onRuntimeEvent(hasSingleBucket || hasBuckets
                ? { kind: 'snapshot', observedAt: Date.now(), payload: message.result }
                : { kind: 'unavailable', observedAt: Date.now() });
        }
    }

    async handleNotification(method, params) {
        if (method === 'turn/started') {
            this.activeItems.clear();
            this.assistantItemOrder = [];
            this.assistantStreams.clear();
            this.completedItemIds.clear();
            this.turnContextWindowUsage = undefined;
            this.activeTurnId = params.turn?.id ?? params.turnId;
            await this.onEvent({ turnId: this.activeTurnId, type: 'turnStarted' });
            return;
        }
        if (method === 'serverRequest/resolved') {
            await this.handleApprovalResolved(params);
            return;
        }
        if (method === 'item/started') {
            await this.handleItemStarted(method, params.item);
            return;
        }
        if (method === 'item/agentMessage/delta') {
            const trackedItem = await this.requireActiveItem(method, params.itemId, 'agentMessage');
            if (!trackedItem) return;
            trackedItem.assistantText = trackedItem.assistantText || params.delta.length > 0;
            trackedItem.bufferedAssistantText += params.delta;
            await this.flushAssistantStreams();
            return;
        }
        if (method === 'item/reasoning/summaryTextDelta') {
            await this.handleReasoningDelta(method, params, 'summary', params.summaryIndex);
            return;
        }
        if (method === 'item/reasoning/summaryPartAdded') {
            const trackedItem = await this.requireActiveItem(method, params.itemId, 'reasoning');
            if (!trackedItem) return;
            trackedItem.event = {
                ...trackedItem.event,
                summary: eventTextParts(trackedItem.event, 'summary', params.summaryIndex),
            };
            await this.emitEvent(trackedItem.event);
            return;
        }
        if (method === 'item/reasoning/textDelta') {
            await this.handleReasoningDelta(method, params, 'details', params.contentIndex);
            return;
        }
        if (method === 'item/commandExecution/outputDelta') {
            const trackedItem = await this.requireActiveItem(method, params.itemId, 'commandExecution');
            if (!trackedItem) return;
            trackedItem.event = { ...trackedItem.event, content: `${trackedItem.event.content}${params.delta}` };
            await this.emitEvent(trackedItem.event);
            return;
        }
        if (method === 'item/plan/delta') {
            const trackedItem = await this.requireActiveItem(method, params.itemId, 'plan');
            if (!trackedItem) return;
            trackedItem.event = { ...trackedItem.event, content: `${trackedItem.event.content}${params.delta}` };
            await this.emitEvent(trackedItem.event);
            return;
        }
        if (method === 'thread/tokenUsage/updated') {
            const usage = codexUsage(params);
            if (!usage) return;
            this.turnContextWindowUsage = codexContextWindowUsage(params);
            this.turnUsage = usage;
            await this.onEvent({ type: 'usage', usage });
            return;
        }
        if (method === 'account/rateLimits/updated') {
            await this.onRuntimeEvent({ kind: 'update', observedAt: Date.now(), payload: params });
            return;
        }
        if (method === 'item/completed') {
            await this.handleItemCompleted(method, params.item);
            return;
        }
        const normalizedSystemEvent = systemEvent(method, params);
        if (normalizedSystemEvent) {
            await this.emitEvent(normalizedSystemEvent);
            return;
        }
        if (method === 'error') {
            const content = params.error?.message ?? 'Codex turn failed';
            await this.emitEvent({
                content,
                label: 'Turn failure',
                providerItemId: `system:${this.activeTurnId ?? 'unknown-turn'}:error`,
                status: 'failed',
                type: 'system',
            });
            await this.onEvent({ content, type: 'fatal' });
            return;
        }
        if (method === 'turn/completed') {
            const error = params.turn?.status === 'failed'
                ? params.turn.error?.message ?? 'Codex turn failed'
                : null;
            if (error) {
                await this.emitEvent({
                    content: error,
                    label: 'Turn failure',
                    providerItemId: `system:${params.turn?.id ?? this.activeTurnId ?? 'unknown-turn'}:turn/completed`,
                    status: 'failed',
                    type: 'system',
                });
            }
            const completedTurnId = params.turn?.id ?? this.activeTurnId;
            await this.resolveApprovalsForTurn(completedTurnId);
            this.activeTurnId = null;
            const contextWindowUsage = this.turnContextWindowUsage;
            await this.onEvent({
                ...(contextWindowUsage !== undefined ? { contextWindowUsage } : {}),
                error,
                type: 'turnCompleted',
                usage: this.turnUsage,
            });
            this.turnContextWindowUsage = undefined;
            this.turnUsage = null;
            return;
        }
        if (method?.startsWith('item/') && typeof params.itemId === 'string') {
            await this.emitDiagnostic(method, null, params.itemId);
        }
    }

    async handleApprovalResolved(params) {
        const pendingApproval = this.pendingApprovals.get(params.requestId);
        if (!pendingApproval) return;
        if (params.threadId !== pendingApproval.approval.threadId) {
            throw new Error(`Mismatched Codex approval resolution thread id: ${params.threadId}`);
        }
        this.pendingApprovals.delete(params.requestId);
        await this.onEvent({ requestId: params.requestId, type: 'approvalResolved' });
    }

    async resolveApprovalsForTurn(turnId) {
        for (const [requestId, pendingApproval] of this.pendingApprovals) {
            if (pendingApproval.approval.turnId !== turnId) continue;
            this.pendingApprovals.delete(requestId);
            await this.onEvent({ requestId, type: 'approvalResolved' });
        }
    }

    async handleItemStarted(method, item) {
        if (!item || typeof item.id !== 'string' || typeof item.type !== 'string') {
            await this.emitDiagnostic(method, item?.type, item?.id);
            return;
        }
        if (this.activeItems.has(item.id) || this.completedItemIds.has(item.id)) {
            await this.emitDiagnostic(method, item.type, item.id);
            return;
        }
        const event = normalizeCodexEvent(item, 'inProgress');
        const knownNonEvent = CODEX_NON_EVENT_ITEM_TYPES.has(item.type);
        const trackedItem = {
            event,
            assistantCompleted: false,
            assistantText: false,
            bufferedAssistantText: '',
            item,
            itemType: item.type,
        };
        this.activeItems.set(item.id, trackedItem);
        if (item.type === 'agentMessage') {
            this.assistantItemOrder.push(item.id);
            this.assistantStreams.set(item.id, trackedItem);
            await this.onEvent({ itemId: item.id, type: 'assistantStarted' });
        }
        if (event) {
            await this.emitEvent(event);
            return;
        }
        if (!knownNonEvent) await this.emitDiagnostic(method, item.type, item.id);
    }

    async handleItemCompleted(method, item) {
        if (!item || typeof item.id !== 'string' || typeof item.type !== 'string') {
            await this.emitDiagnostic(method, item?.type, item?.id);
            return;
        }
        if (this.completedItemIds.has(item.id)) {
            await this.emitDiagnostic(method, item.type, item.id);
            return;
        }
        const trackedItem = this.activeItems.get(item.id);
        if (!trackedItem) await this.emitDiagnostic(method, item.type, item.id);
        if (trackedItem && trackedItem.itemType !== item.type) {
            await this.emitDiagnostic(method, item.type, item.id);
            return;
        }
        if (item.type === 'agentMessage' && trackedItem) {
            trackedItem.assistantCompleted = true;
            await this.flushAssistantStreams();
        }
        const changedPaths = codexChangedPaths(item, this.rootPath);
        if (changedPaths.length > 0) await this.onEvent({ paths: changedPaths, type: 'changedPaths' });
        const event = normalizeCodexEvent(item, 'completed');
        if (event) await this.emitEvent(event);
        if (!event && !CODEX_NON_EVENT_ITEM_TYPES.has(item.type) && trackedItem) {
            await this.emitDiagnostic(method, item.type, item.id);
        }
        this.activeItems.delete(item.id);
        this.completedItemIds.add(item.id);
    }

    async requireActiveItem(method, itemId, expectedType) {
        const trackedItem = this.activeItems.get(itemId);
        if (!trackedItem || trackedItem.itemType !== expectedType || this.completedItemIds.has(itemId)) {
            await this.emitDiagnostic(method, expectedType, itemId);

            return null;
        }

        return trackedItem;
    }

    async handleReasoningDelta(method, params, field, index) {
        const trackedItem = await this.requireActiveItem(method, params.itemId, 'reasoning');
        if (!trackedItem || !Number.isSafeInteger(index) || index < 0) {
            if (trackedItem) await this.emitDiagnostic(method, 'reasoning', params.itemId);
            return;
        }
        const parts = eventTextParts(trackedItem.event, field, index);
        parts[index] += params.delta;
        const event = { ...trackedItem.event, [field]: parts };
        trackedItem.event = {
            ...event,
            content: event.summary.length > 0 ? event.summary.join('\n\n') : event.details.join('\n\n'),
        };
        await this.emitEvent(trackedItem.event);
    }

    async flushAssistantStreams() {
        while (this.assistantItemOrder.length > 0) {
            const itemId = this.assistantItemOrder[0];
            const stream = this.assistantStreams.get(itemId);
            if (!stream) {
                this.assistantItemOrder.shift();
                continue;
            }
            if (stream.bufferedAssistantText.length > 0) {
                const content = stream.bufferedAssistantText;
                stream.bufferedAssistantText = '';
                await this.onEvent({ content, itemId, type: 'assistant' });
            }
            if (!stream.assistantCompleted) return;
            if (stream.assistantText) await this.onEvent({ content: '\n\n', itemId, type: 'assistant' });
            this.assistantStreams.delete(itemId);
            this.assistantItemOrder.shift();
        }
    }

    async emitEvent(event) {
        await this.onEvent({ event, type: 'event' });
    }

    async emitDiagnostic(method, itemType, itemId) {
        const event = diagnosticEvent(method, itemType, itemId, this.diagnosticSequence);
        this.diagnosticSequence += 1;
        await this.emitEvent(event);
    }
}

function createAgentStreamingAdapter(
    agent,
    writeLine,
    onEvent,
    rootPath,
    providerConversationId = null,
    onRuntimeEvent = async () => undefined,
) {
    if (agent === 'claude') return new ClaudeStreamingAdapter(writeLine, onEvent, rootPath, providerConversationId);
    if (agent === 'codex') {
        return new CodexStreamingAdapter(writeLine, onEvent, rootPath, providerConversationId, onRuntimeEvent);
    }

    throw new Error(`Agent profile does not support streaming: ${agent}`);
}

module.exports = { createAgentStreamingAdapter };

const {
    accumulateUsage,
    createProviderEventEntry,
    createEventEntry,
    updateProviderSession,
} = require('./agent_conversation');
const { emitRunEvent, hasPendingInteraction } = require('./agent_run_state');
const {
    appendAssistantOutput,
    appendDiagnosticContent,
    completeAssistantOutput,
    lastMessageEntry,
    nextRunSequence,
    replaceAssistantOutput,
    startAssistantItem,
} = require('./agent_run_transcript');
const { redactConversationEvent, redactSecrets } = require('./agent_secret_redaction');
const { requireString } = require('./agent_run_validation');

function handleSessionStarted(service, run, event) {
    run.providerConversationId = event.conversationId;
}

function handleTurnStarted(service, run) {
    run.assistantItemIndex = 0;
    run.assistantItems.clear();
    run.currentAssistantMessageId = null;
    run.liveTurnUsage = null;
    run.turnStarted = true;
}

function handleUsage(service, run, event) {
    run.liveTurnUsage = event.usage;
    const usage = accumulateUsage(run.conversation.usage, event.usage);
    emitRunEvent(run, { type: 'usage', usage });
}

function handleAssistantStarted(service, run, event, timestamp) {
    const item = startAssistantItem(run, requireString(event.itemId, 'assistant item id'), timestamp);
    emitRunEvent(run, { content: '', messageId: item.messageId, sequence: item.sequence, type: 'output' });
}

function handleAssistant(service, run, event, timestamp) {
    const safeContent = redactSecrets(event.content, run.secretValues);
    const itemId = run.agent === 'codex'
        ? requireString(event.itemId, 'assistant item id')
        : event.itemId;
    const { message, segment } = appendAssistantOutput(run, safeContent, timestamp, itemId);
    if (segment.length > 0) {
        emitRunEvent(run, { content: segment, messageId: message.id, sequence: message.sequence, type: 'output' });
    }
}

function handleAssistantCompleted(service, run, event, timestamp) {
    const safeContent = redactSecrets(event.content, run.secretValues);
    const itemId = requireString(event.itemId, 'assistant item id');
    const { message, previousContent, replaced } = replaceAssistantOutput(run, safeContent, timestamp, itemId);
    if (!replaced) return;

    emitRunEvent(run, {
        content: safeContent,
        messageId: message.id,
        previousContent,
        replace: true,
        sequence: message.sequence,
        type: 'output',
    });
}

function handleChangedPaths(service, run, event) {
    event.paths.forEach((filePath) => run.changedPaths.add(filePath));
}

/** Provider events are keyed by `providerItemId` so a later revision of the same item replaces its entry. */
function handleEvent(service, run, event, timestamp) {
    const safeEvent = redactConversationEvent(event.event, run.secretValues);
    const providerItemId = requireString(safeEvent.providerItemId, 'event providerItemId');
    const currentIndex = run.providerEventEntryIndexes.get(providerItemId);
    let eventEntry;
    if (currentIndex !== undefined) {
        const current = run.conversation.entries[currentIndex];
        eventEntry = createProviderEventEntry(safeEvent, current.id, timestamp, current.sequence);
        run.conversation.entries[currentIndex] = eventEntry;
    } else {
        const previousEntry = run.conversation.entries.at(-1);
        if (safeEvent.type === 'diagnostic' && previousEntry?.kind === 'event' && previousEntry.type === 'diagnostic') {
            eventEntry = appendDiagnosticContent(previousEntry, safeEvent.content);
            run.conversation.entries[run.conversation.entries.length - 1] = eventEntry;
        } else {
            const sequence = nextRunSequence(run);
            eventEntry = createProviderEventEntry(
                safeEvent,
                `${run.id}-event-${sequence}`,
                timestamp,
                sequence,
            );
            run.providerEventEntryIndexes.set(providerItemId, run.conversation.entries.length);
            run.conversation.entries.push(eventEntry);
        }
    }
    emitRunEvent(run, { event: eventEntry, type: 'agentEvent' });
}

function handleTranscript(service, run, event, timestamp) {
    const safeContent = redactSecrets(event.content, run.secretValues);
    run.conversation.entries.push(createEventEntry(
        `${run.id}-provider-${run.conversation.entries.length}`,
        event.toolType,
        safeContent,
        timestamp,
        nextRunSequence(run),
    ));
}

function handleError(service, run, event) {
    service.recordOutput(run.id, 'stderr', event.content);
}

function handleFatal(service, run, event) {
    service.failStreamingRun(run, new Error(event.content));
}

function handleSessionFailed(service, run, event) {
    run.missingSession = event.missingSession;
    service.failStreamingRun(run, new Error(event.content));
}

async function handleQuestion(service, run, event) {
    run.conversation.status = 'waitingForInput';
    run.waitingForQuestion = true;
    run.pendingQuestions = event.questions;
    await service.persistCheckpoint(run);
    emitRunEvent(run, { questions: event.questions, requestId: event.requestId, state: 'waitingForInput', type: 'question' });
}

async function handleApproval(service, run, event) {
    const requestId = event.approval.requestId;
    if (run.pendingApprovals.has(requestId)) throw new Error(`Duplicate agent approval request id: ${requestId}`);
    run.pendingApprovals.set(requestId, { ...event.approval, submitted: false });
    run.conversation.status = 'waitingForInput';
    await service.persistCheckpoint(run);
    emitRunEvent(run, { approval: event.approval, state: 'waitingForInput', type: 'approval' });
}

function handleApprovalSubmitted(service, run, event) {
    const approval = run.pendingApprovals.get(event.requestId);
    if (!approval) return;
    approval.submitted = true;
    emitRunEvent(run, { requestId: event.requestId, type: 'approvalSubmitted' });
}

function handleApprovalResolved(service, run, event) {
    if (!run.pendingApprovals.delete(event.requestId)) return;
    const state = hasPendingInteraction(run) ? 'waitingForInput' : 'running';
    run.conversation.status = state;
    emitRunEvent(run, { requestId: event.requestId, state, type: 'approvalResolved' });
    emitRunEvent(run, { state, type: 'state' });
}

/**
 * End of a streaming turn: settle the assistant message, then either shut the process down,
 * send the message queued while the turn was running, or park the run waiting for input.
 */
async function handleTurnCompleted(service, run, event, timestamp) {
    completeAssistantOutput(run, timestamp);
    run.turnActive = false;
    run.waitingForQuestion = false;
    run.pendingApprovals.clear();
    run.missingSession = run.missingSession || event.missingSession;
    if (event.missingSession) run.finishing = true;
    if (event.usage) {
        run.liveTurnUsage = event.usage;
        run.conversation.usage = accumulateUsage(run.conversation.usage, run.liveTurnUsage);
        run.liveTurnUsage = null;
    }
    if (event.contextWindowUsage !== undefined) {
        if (event.contextWindowUsage) run.conversation.contextWindowUsage = event.contextWindowUsage;
        else delete run.conversation.contextWindowUsage;
    }
    if (event.usage || event.contextWindowUsage !== undefined) {
        emitRunEvent(run, {
            ...(event.contextWindowUsage !== undefined ? { contextWindowUsage: event.contextWindowUsage } : {}),
            type: 'usage',
            usage: run.conversation.usage,
        });
    }
    if (event.error) {
        service.failStreamingRun(run, new Error(event.error));
        return;
    }
    if (run.finishing) {
        service.beginFinishShutdown(run);
        return;
    }
    if (run.queuedMessage) {
        const { content, revision } = run.queuedMessage;
        run.conversation.status = 'waitingForInput';
        await service.sendStreamingMessage(run, content);
        run.queuedMessage = null;
        run.sentQueuedMessageRevision = revision;
        return;
    }
    const synchronizedMessage = lastMessageEntry(run.conversation);
    if (synchronizedMessage) updateProviderSession(run, synchronizedMessage.id, timestamp);
    run.conversation.status = 'waitingForInput';
    run.conversation.completedAt = null;
    await service.persistCheckpoint(run);
    emitRunEvent(run, { state: 'waitingForInput', type: 'state' });
}

/** Keyed by streaming event type; unknown types are ignored. Each handler takes `(service, run, event, timestamp)`. */
const STREAMING_EVENT_HANDLERS = {
    approval: handleApproval,
    approvalResolved: handleApprovalResolved,
    approvalSubmitted: handleApprovalSubmitted,
    assistant: handleAssistant,
    assistantCompleted: handleAssistantCompleted,
    assistantStarted: handleAssistantStarted,
    changedPaths: handleChangedPaths,
    error: handleError,
    event: handleEvent,
    fatal: handleFatal,
    question: handleQuestion,
    sessionFailed: handleSessionFailed,
    sessionStarted: handleSessionStarted,
    transcript: handleTranscript,
    turnCompleted: handleTurnCompleted,
    turnStarted: handleTurnStarted,
    usage: handleUsage,
};

module.exports = { STREAMING_EVENT_HANDLERS };

